/* Business Leadership: three practice items and one reserved item per topic.
 * Skill supplements and project scenarios are examination-only. Context is
 * module-qualified where a title is taught in more than one setting. */
(function(){
 if(typeof window==='undefined')return;
 var DATA=[
  {"key":"M1:Welcome to the Course","rows":[{"q":"Welcome to the Course: How can a learner move beyond watching demonstrations?","opts":["Collect evidence of impact","Apply a leadership skill","Reflect on feedback","Plan the next improvement"],"correct":1,"exp":"Practising a leadership behavior in a realistic task turns information into usable skill.","module":1,"topic":"M1:Welcome to the Course"},{"q":"Welcome to the Course: What supports a claim that a leadership project helped a team?","opts":["Apply a leadership skill","Reflect on feedback","Plan the next improvement","Collect evidence of impact"],"correct":3,"exp":"Record the baseline, intervention and outcome rather than relying only on personal impressions.","module":1,"topic":"M1:Welcome to the Course"},{"q":"Welcome to the Course: What should a learner do with conflicting comments from teammates?","opts":["Apply a leadership skill","Collect evidence of impact","Reflect on feedback","Plan the next improvement"],"correct":2,"exp":"Compare the comments with observed behavior and context before choosing a development priority.","module":1,"topic":"M1:Welcome to the Course"},{"q":"Welcome to the Course: A project has ended and lessons are documented. What turns learning into continuing development?","opts":["Apply a leadership skill","Collect evidence of impact","Plan the next improvement","Reflect on feedback"],"correct":2,"exp":"Choose a specific next action, owner, date and success measure based on the project review.","module":1,"topic":"M1:Welcome to the Course"}]},
  {"key":"M1:What is Leadership?","rows":[{"q":"What is Leadership?: A person without a management title helps colleagues align around a shared goal. What are they demonstrating?","opts":["Influence toward shared purpose","Formal authority","Technical expertise","Administrative control"],"correct":0,"exp":"Leadership can emerge through influence and service without a formal title.","module":1,"topic":"M1:What is Leadership?"},{"q":"What is Leadership?: Which concept gives a manager the organizational right to approve a purchase?","opts":["Influence toward shared purpose","Technical expertise","Formal authority","Administrative control"],"correct":2,"exp":"Formal authority comes from an assigned role and its defined decision rights.","module":1,"topic":"M1:What is Leadership?"},{"q":"What is Leadership?: A specialist can repair a machine but does not coordinate people. Which capability is most directly shown?","opts":["Influence toward shared purpose","Formal authority","Technical expertise","Administrative control"],"correct":2,"exp":"Technical expertise is knowledge of a task; it does not by itself establish people leadership.","module":1,"topic":"M1:What is Leadership?"},{"q":"What is Leadership?: Which concept describes tracking compliance with a routine procedure?","opts":["Influence toward shared purpose","Formal authority","Administrative control","Technical expertise"],"correct":2,"exp":"Administrative control checks execution against established requirements; leadership also develops purpose and commitment.","module":1,"topic":"M1:What is Leadership?"}]},
  {"key":"M1:Leadership vs. Management","rows":[{"q":"Leadership vs. Management: Which activity establishes where an organization should go and why?","opts":["Organizing resources","Building commitment","Setting direction","Monitoring execution"],"correct":2,"exp":"Setting direction frames purpose and future priorities rather than merely scheduling existing work.","module":1,"topic":"M1:Leadership vs. Management"},{"q":"Leadership vs. Management: Which activity allocates staff and equipment to an approved plan?","opts":["Setting direction","Building commitment","Monitoring execution","Organizing resources"],"correct":3,"exp":"Organizing resources translates an agreed direction into operational capacity.","module":1,"topic":"M1:Leadership vs. Management"},{"q":"Leadership vs. Management: Which activity helps people understand and support a challenging new goal?","opts":["Building commitment","Setting direction","Organizing resources","Monitoring execution"],"correct":0,"exp":"Building commitment connects the goal with stakeholder concerns and shared value.","module":1,"topic":"M1:Leadership vs. Management"},{"q":"Leadership vs. Management: Which activity checks actual delivery against a timetable?","opts":["Monitoring execution","Setting direction","Organizing resources","Building commitment"],"correct":0,"exp":"Monitoring execution provides control information; effective leaders combine this with direction and commitment.","module":1,"topic":"M1:Leadership vs. Management"}]},
  {"key":"M1:Characteristics of Great Leaders","rows":[{"q":"Characteristics of Great Leaders: A leader reports an inconvenient error accurately. Which characteristic is most directly demonstrated?","opts":["Empathy","Integrity","Adaptability","Accountability"],"correct":1,"exp":"Integrity means aligning conduct and truthful reporting with stated values even under pressure.","module":1,"topic":"M1:Characteristics of Great Leaders"},{"q":"Characteristics of Great Leaders: A leader listens to how a new shift affects caregivers before deciding. Which characteristic is shown?","opts":["Integrity","Empathy","Adaptability","Accountability"],"correct":1,"exp":"Empathy considers other people's experience without requiring automatic agreement with every request.","module":1,"topic":"M1:Characteristics of Great Leaders"},{"q":"Characteristics of Great Leaders: Evidence shows an approach is failing, and a leader changes it. Which characteristic is shown?","opts":["Adaptability","Integrity","Empathy","Accountability"],"correct":0,"exp":"Adaptability changes methods in response to evidence while preserving the underlying purpose.","module":1,"topic":"M1:Characteristics of Great Leaders"},{"q":"Characteristics of Great Leaders: A leader accepts responsibility for a decision and organizes corrective action. Which characteristic is shown?","opts":["Integrity","Empathy","Adaptability","Accountability"],"correct":3,"exp":"Accountability includes explaining decisions, owning consequences and following through on correction.","module":1,"topic":"M1:Characteristics of Great Leaders"}]},
  {"key":"M1:Leadership Styles","rows":[{"q":"Leadership Styles: An urgent incident requires clear instructions from the responsible incident lead. Which style best fits immediate coordination?","opts":["Participative leadership","Directive leadership","Coaching leadership","Delegative leadership"],"correct":1,"exp":"Directive leadership can clarify urgent actions when delay is costly and responsibilities must be explicit.","module":1,"topic":"M1:Leadership Styles"},{"q":"Leadership Styles: A knowledgeable team helps compare options before its leader decides. Which style is used?","opts":["Participative leadership","Directive leadership","Coaching leadership","Delegative leadership"],"correct":0,"exp":"Participative leadership involves relevant voices while keeping decision authority clear.","module":1,"topic":"M1:Leadership Styles"},{"q":"Leadership Styles: A leader uses questions and feedback to develop a colleague's capability. Which style is used?","opts":["Directive leadership","Coaching leadership","Participative leadership","Delegative leadership"],"correct":1,"exp":"Coaching builds the learner's reasoning and skill rather than supplying every answer.","module":1,"topic":"M1:Leadership Styles"},{"q":"Leadership Styles: A capable colleague receives a defined outcome and freedom to choose methods. Which style is used?","opts":["Directive leadership","Participative leadership","Coaching leadership","Delegative leadership"],"correct":3,"exp":"Delegative leadership grants appropriate autonomy with boundaries and agreed review points.","module":1,"topic":"M1:Leadership Styles"}]},
  {"key":"M1:The Role of a Business Leader","rows":[{"q":"The Role of a Business Leader: Departments pursue incompatible goals. Which responsibility should the business leader address first?","opts":["Develop people","Allocate resources","Review stakeholder outcomes","Align strategic priorities"],"correct":3,"exp":"Aligning priorities reduces conflicting work and connects departments to common strategic outcomes.","module":1,"topic":"M1:The Role of a Business Leader"},{"q":"The Role of a Business Leader: A successor lacks experience leading meetings. Which responsibility includes arranging supported practice?","opts":["Align strategic priorities","Allocate resources","Review stakeholder outcomes","Develop people"],"correct":3,"exp":"Developing people builds capability through appropriate opportunities, support and feedback.","module":1,"topic":"M1:The Role of a Business Leader"},{"q":"The Role of a Business Leader: Two approved initiatives compete for the same equipment. Which responsibility resolves the capacity decision?","opts":["Align strategic priorities","Develop people","Allocate resources","Review stakeholder outcomes"],"correct":2,"exp":"Resource allocation weighs priorities, constraints and consequences rather than promising capacity twice.","module":1,"topic":"M1:The Role of a Business Leader"},{"q":"The Role of a Business Leader: A profitable initiative increases customer complaints. Which responsibility examines the combined effect?","opts":["Review stakeholder outcomes","Align strategic priorities","Develop people","Allocate resources"],"correct":0,"exp":"Stakeholder outcome review considers customer, people and operational effects alongside financial results.","module":1,"topic":"M1:The Role of a Business Leader"}]},
  {"key":"M1:Course Roadmap","rows":[{"q":"Course Roadmap: Why study trust and decision-making before designing a large leadership project?","opts":["Foundations before application","Cross-module integration","Evidence portfolio","Completion review"],"correct":0,"exp":"Foundations provide concepts needed to interpret later complex situations responsibly.","module":1,"topic":"M1:Course Roadmap"},{"q":"Course Roadmap: A capstone combines strategy, finance and team leadership. What learning process does this represent?","opts":["Cross-module integration","Foundations before application","Evidence portfolio","Completion review"],"correct":0,"exp":"Integration connects capabilities that business decisions require together.","module":1,"topic":"M1:Course Roadmap"},{"q":"Course Roadmap: Where should a learner organize deliverables, feedback and reflections from different modules?","opts":["Foundations before application","Cross-module integration","Evidence portfolio","Completion review"],"correct":2,"exp":"An evidence portfolio documents work and learning across the course.","module":1,"topic":"M1:Course Roadmap"},{"q":"Course Roadmap: What should precede requesting an official TIH completion review?","opts":["Foundations before application","Cross-module integration","Evidence portfolio","Completion review"],"correct":3,"exp":"Check the Learning Hub's current requirements and confirm that required work and assessments are complete.","module":1,"topic":"M1:Course Roadmap"}]},
  {"key":"M1:Professional Ethics","rows":[{"q":"Professional Ethics: A supplier is owned by a leader's relative. What should the leader do before taking part in selection?","opts":["Protect confidential information","Disclose a conflict","Apply fair criteria","Correct misleading reporting"],"correct":1,"exp":"Disclosure enables an appropriate independent decision process and any required recusal.","module":1,"topic":"M1:Professional Ethics"},{"q":"Professional Ethics: A colleague requests private personnel records without a work-related authorization. Which duty is relevant?","opts":["Protect confidential information","Disclose a conflict","Apply fair criteria","Correct misleading reporting"],"correct":0,"exp":"Confidential information should be shared only through authorized, appropriate channels.","module":1,"topic":"M1:Professional Ethics"},{"q":"Professional Ethics: Two candidates must be assessed against the same published role requirements. Which ethical practice applies?","opts":["Apply fair criteria","Disclose a conflict","Protect confidential information","Correct misleading reporting"],"correct":0,"exp":"Consistent job-related criteria support fairness and reduce favoritism.","module":1,"topic":"M1:Professional Ethics"},{"q":"Professional Ethics: A presentation deliberately omits a material limitation. Which action restores reporting integrity?","opts":["Correct misleading reporting","Disclose a conflict","Protect confidential information","Apply fair criteria"],"correct":0,"exp":"Correcting the report gives decision makers the relevant facts and uncertainties.","module":1,"topic":"M1:Professional Ethics"}]},
  {"key":"M2:Leadership Principles","rows":[{"q":"Leadership Principles: Which principle connects individual work to an agreed organizational goal?","opts":["Consistency of conduct","Shared purpose","Service to stakeholders","Learning from evidence"],"correct":1,"exp":"Shared purpose explains why work matters and helps coordinate competing activities.","module":2,"topic":"M2:Leadership Principles"},{"q":"Leadership Principles: A leader requires punctuality but routinely arrives late without explanation. Which principle is undermined?","opts":["Shared purpose","Service to stakeholders","Learning from evidence","Consistency of conduct"],"correct":3,"exp":"Consistency between expectations and personal conduct supports credibility.","module":2,"topic":"M2:Leadership Principles"},{"q":"Leadership Principles: Whose interests should leadership consider when exercising organizational power?","opts":["Shared purpose","Consistency of conduct","Learning from evidence","Service to stakeholders"],"correct":3,"exp":"Service considers affected stakeholders and responsibilities rather than only the leader's status.","module":2,"topic":"M2:Leadership Principles"},{"q":"Leadership Principles: A pilot contradicts the team's original assumption. Which principle supports adjusting the plan?","opts":["Shared purpose","Consistency of conduct","Service to stakeholders","Learning from evidence"],"correct":3,"exp":"Learning from evidence replaces unsupported certainty with accountable adaptation.","module":2,"topic":"M2:Leadership Principles"}]},
  {"key":"M2:Self-Leadership","rows":[{"q":"Self-Leadership: What should a leader examine before trying to change a recurring reactive habit?","opts":["Recognize personal patterns","Set behavioral goals","Manage attention","Review personal progress"],"correct":0,"exp":"Recognizing triggers, thoughts and behaviors helps identify the actual development need.","module":2,"topic":"M2:Self-Leadership"},{"q":"Self-Leadership: What turns a vague wish to be more reliable into an actionable commitment?","opts":["Set behavioral goals","Recognize personal patterns","Manage attention","Review personal progress"],"correct":0,"exp":"A behavioral goal specifies observable conduct, a timeframe and evidence of success.","module":2,"topic":"M2:Self-Leadership"},{"q":"Self-Leadership: A leader repeatedly interrupts important work to check nonurgent messages. Which skill needs improvement?","opts":["Recognize personal patterns","Manage attention","Set behavioral goals","Review personal progress"],"correct":1,"exp":"Attention management uses priorities and boundaries to protect focused work.","module":2,"topic":"M2:Self-Leadership"},{"q":"Self-Leadership: What shows whether a new leadership habit is working over several weeks?","opts":["Recognize personal patterns","Set behavioral goals","Review personal progress","Manage attention"],"correct":2,"exp":"Regular review compares behavior and outcomes with the stated goal and feedback.","module":2,"topic":"M2:Self-Leadership"}]},
  {"key":"M2:Emotional Intelligence","rows":[{"q":"Emotional Intelligence: A leader notices that criticism triggers defensiveness. Which capability is being used?","opts":["Self-regulation","Self-awareness","Empathy","Relationship management"],"correct":1,"exp":"Self-awareness identifies emotional responses before they automatically drive behavior.","module":2,"topic":"M2:Emotional Intelligence"},{"q":"Emotional Intelligence: A leader pauses before responding angrily and chooses a constructive reply. Which capability is shown?","opts":["Self-awareness","Empathy","Relationship management","Self-regulation"],"correct":3,"exp":"Self-regulation manages the response to emotion without denying the emotion itself.","module":2,"topic":"M2:Emotional Intelligence"},{"q":"Emotional Intelligence: A leader considers why an employee may be anxious about a change. Which capability is shown?","opts":["Empathy","Self-awareness","Self-regulation","Relationship management"],"correct":0,"exp":"Empathy seeks to understand another person's perspective and experience.","module":2,"topic":"M2:Emotional Intelligence"},{"q":"Emotional Intelligence: A leader helps colleagues repair a strained working agreement. Which capability is shown?","opts":["Relationship management","Self-awareness","Self-regulation","Empathy"],"correct":0,"exp":"Relationship management uses communication and conflict skills to maintain constructive cooperation.","module":2,"topic":"M2:Emotional Intelligence"}]},
  {"key":"M2:Personal Values","rows":[{"q":"Personal Values: What starts a useful personal values exercise?","opts":["Recognize a value conflict","Set a behavioral boundary","Identify a core value","Review value alignment"],"correct":2,"exp":"Naming a value and explaining why it matters provides a basis for examining conduct.","module":2,"topic":"M2:Personal Values"},{"q":"Personal Values: A growth target competes with a promise of safe workloads. What should be made explicit?","opts":["Identify a core value","Set a behavioral boundary","Review value alignment","Recognize a value conflict"],"correct":3,"exp":"A value conflict requires examining trade-offs and consequences rather than hiding the tension.","module":2,"topic":"M2:Personal Values"},{"q":"Personal Values: What translates an integrity value into a clear limit on conduct?","opts":["Set a behavioral boundary","Identify a core value","Recognize a value conflict","Review value alignment"],"correct":0,"exp":"A behavioral boundary states an action the leader will or will not accept, such as falsifying results.","module":2,"topic":"M2:Personal Values"},{"q":"Personal Values: How can a leader check whether stated values actually guide decisions?","opts":["Review value alignment","Identify a core value","Recognize a value conflict","Set a behavioral boundary"],"correct":0,"exp":"Compare real choices and their effects with the values, including difficult cases.","module":2,"topic":"M2:Personal Values"}]},
  {"key":"M2:Building Trust","rows":[{"q":"Building Trust: Which action builds confidence that a leader can perform the role?","opts":["Honor commitments","Explain decisions openly","Demonstrate competence","Acknowledge and repair harm"],"correct":2,"exp":"Competence is demonstrated through preparation, sound judgment and reliable delivery.","module":2,"topic":"M2:Building Trust"},{"q":"Building Trust: A leader promises a follow-up by Friday. Which behavior most directly supports reliability?","opts":["Demonstrate competence","Explain decisions openly","Honor commitments","Acknowledge and repair harm"],"correct":2,"exp":"Keeping the promise, or promptly explaining a necessary renegotiation, supports trust.","module":2,"topic":"M2:Building Trust"},{"q":"Building Trust: People do not understand why priorities changed. Which practice reduces avoidable uncertainty?","opts":["Demonstrate competence","Explain decisions openly","Honor commitments","Acknowledge and repair harm"],"correct":1,"exp":"Transparent reasoning explains relevant evidence and boundaries without exposing protected information.","module":2,"topic":"M2:Building Trust"},{"q":"Building Trust: A leader's unfair decision damaged a colleague. What supports rebuilding trust?","opts":["Acknowledge and repair harm","Demonstrate competence","Honor commitments","Explain decisions openly"],"correct":0,"exp":"Repair requires acknowledging the harm, taking responsibility and following through on corrective action.","module":2,"topic":"M2:Building Trust"}]},
  {"key":"M2:Decision-Making","rows":[{"q":"Decision-Making: A team debates solutions but cannot state the problem it must resolve. What is missing?","opts":["Compare alternatives","Test assumptions","Assign action and review","Define the decision"],"correct":3,"exp":"A clear decision statement identifies the objective, scope, authority and deadline.","module":2,"topic":"M2:Decision-Making"},{"q":"Decision-Making: What should a leader do before choosing between two credible suppliers?","opts":["Define the decision","Test assumptions","Assign action and review","Compare alternatives"],"correct":3,"exp":"Compare options against agreed criteria such as quality, cost, reliability and risk.","module":2,"topic":"M2:Decision-Making"},{"q":"Decision-Making: A plan assumes demand will double without supporting data. What should be done?","opts":["Define the decision","Test assumptions","Compare alternatives","Assign action and review"],"correct":1,"exp":"Test the assumption using evidence or sensitivity analysis before relying on it.","module":2,"topic":"M2:Decision-Making"},{"q":"Decision-Making: A decision was approved but no one knows who implements it. What completes the process?","opts":["Define the decision","Assign action and review","Compare alternatives","Test assumptions"],"correct":1,"exp":"Assign an accountable owner, resources, communication and a review date.","module":2,"topic":"M2:Decision-Making"}]},
  {"key":"M2:Accountability","rows":[{"q":"Accountability: What prevents a task from belonging vaguely to everyone?","opts":["Visible commitments","Clear ownership","Evidence-based review","Corrective follow-through"],"correct":1,"exp":"Clear ownership names who is responsible while specifying supporting roles.","module":2,"topic":"M2:Accountability"},{"q":"Accountability: What helps a team know the agreed deliverable and deadline?","opts":["Clear ownership","Visible commitments","Evidence-based review","Corrective follow-through"],"correct":1,"exp":"Visible commitments record expectations so they can be checked consistently.","module":2,"topic":"M2:Accountability"},{"q":"Accountability: What should determine whether an agreed outcome was achieved?","opts":["Clear ownership","Evidence-based review","Visible commitments","Corrective follow-through"],"correct":1,"exp":"Evidence-based review compares actual results with the agreed criteria and context.","module":2,"topic":"M2:Accountability"},{"q":"Accountability: A review identifies a preventable failure. What demonstrates accountability afterward?","opts":["Corrective follow-through","Clear ownership","Visible commitments","Evidence-based review"],"correct":0,"exp":"Corrective follow-through addresses causes, assigns actions and verifies that the correction worked.","module":2,"topic":"M2:Accountability"}]},
  {"key":"M2:Developing Leadership Confidence","rows":[{"q":"Developing Leadership Confidence: What improves confidence before chairing a first stakeholder meeting?","opts":["Seek bounded practice","Prepare for a task","Use specific feedback","Recognize uncertainty honestly"],"correct":1,"exp":"Preparation clarifies the purpose, audience, agenda and likely difficult questions.","module":2,"topic":"M2:Developing Leadership Confidence"},{"q":"Developing Leadership Confidence: How can an emerging leader build confidence without taking uncontrolled risks?","opts":["Prepare for a task","Use specific feedback","Recognize uncertainty honestly","Seek bounded practice"],"correct":3,"exp":"Supported practice with appropriate boundaries develops experience and judgment.","module":2,"topic":"M2:Developing Leadership Confidence"},{"q":"Developing Leadership Confidence: What feedback is most useful for improving a weak leadership behavior?","opts":["Prepare for a task","Seek bounded practice","Recognize uncertainty honestly","Use specific feedback"],"correct":3,"exp":"Specific observations and examples show what to repeat or change.","module":2,"topic":"M2:Developing Leadership Confidence"},{"q":"Developing Leadership Confidence: How should a confident leader respond to a question they cannot yet answer?","opts":["Prepare for a task","Seek bounded practice","Use specific feedback","Recognize uncertainty honestly"],"correct":3,"exp":"State the limitation and arrange verification rather than inventing certainty.","module":2,"topic":"M2:Developing Leadership Confidence"}]},
  {"key":"M2:Leadership Action Plan","rows":[{"q":"Leadership Action Plan: Which part of an action plan states the capability to improve?","opts":["Practice action","Success evidence","Development objective","Review date"],"correct":2,"exp":"The objective names a specific development need connected to the leader's role.","module":2,"topic":"M2:Leadership Action Plan"},{"q":"Leadership Action Plan: Which part states what the learner will actually do to build the capability?","opts":["Development objective","Practice action","Success evidence","Review date"],"correct":1,"exp":"A practice action is an observable activity such as leading a meeting with feedback.","module":2,"topic":"M2:Leadership Action Plan"},{"q":"Leadership Action Plan: Which part explains how improvement will be judged?","opts":["Success evidence","Development objective","Practice action","Review date"],"correct":0,"exp":"Success evidence may include observed behavior, delivery results and stakeholder feedback.","module":2,"topic":"M2:Leadership Action Plan"},{"q":"Leadership Action Plan: Which part prevents a development plan from remaining indefinitely unexamined?","opts":["Development objective","Practice action","Review date","Success evidence"],"correct":2,"exp":"A scheduled review checks progress and adapts the plan when necessary.","module":2,"topic":"M2:Leadership Action Plan"}]},
  {"key":"M3:Strategic Planning","rows":[{"q":"Strategic Planning: What should precede selecting major strategic initiatives?","opts":["Strategic choice","Implementation roadmap","Strategy review","Diagnosis"],"correct":3,"exp":"Diagnosis examines the current position, stakeholders, evidence, capabilities and constraints.","module":3,"topic":"M3:Strategic Planning"},{"q":"Strategic Planning: A business decides which customer segment to serve and which work to decline. What is this?","opts":["Strategic choice","Diagnosis","Implementation roadmap","Strategy review"],"correct":0,"exp":"Strategic choice establishes priorities and trade-offs rather than a list of all possible activities.","module":3,"topic":"M3:Strategic Planning"},{"q":"Strategic Planning: What connects a chosen strategy to owners, budgets and milestones?","opts":["Diagnosis","Strategic choice","Strategy review","Implementation roadmap"],"correct":3,"exp":"An implementation roadmap translates direction into coordinated actions.","module":3,"topic":"M3:Strategic Planning"},{"q":"Strategic Planning: What should a business do when a major market assumption changes?","opts":["Diagnosis","Strategy review","Strategic choice","Implementation roadmap"],"correct":1,"exp":"Review strategy against new evidence and adjust choices and implementation as needed.","module":3,"topic":"M3:Strategic Planning"}]},
  {"key":"M3:Vision and Mission","rows":[{"q":"Vision and Mission: Which statement describes a desired future organizational position?","opts":["Mission","Strategic objective","Vision","Core value"],"correct":2,"exp":"A vision expresses the future the organization aims to help create.","module":3,"topic":"M3:Vision and Mission"},{"q":"Vision and Mission: Which statement explains the organization's current purpose and whom it serves?","opts":["Mission","Vision","Strategic objective","Core value"],"correct":0,"exp":"A mission describes purpose, service and scope in the present.","module":3,"topic":"M3:Vision and Mission"},{"q":"Vision and Mission: Which statement specifies a measurable result to pursue over a defined period?","opts":["Vision","Mission","Strategic objective","Core value"],"correct":2,"exp":"A strategic objective translates direction into an intended outcome with evidence of progress.","module":3,"topic":"M3:Vision and Mission"},{"q":"Vision and Mission: Which statement identifies a principle that should guide conduct?","opts":["Vision","Mission","Core value","Strategic objective"],"correct":2,"exp":"A core value sets expectations for how the organization pursues its mission.","module":3,"topic":"M3:Vision and Mission"}]},
  {"key":"M3:Setting Business Goals","rows":[{"q":"Setting Business Goals: What is missing from a goal that only says improve the business?","opts":["Measurable indicator","Feasible target","Time boundary","Specific outcome"],"correct":3,"exp":"A specific outcome identifies the particular change the team intends to achieve.","module":3,"topic":"M3:Setting Business Goals"},{"q":"Setting Business Goals: What enables a team to judge progress instead of debating impressions?","opts":["Specific outcome","Measurable indicator","Feasible target","Time boundary"],"correct":1,"exp":"A measurable indicator defines what evidence will show progress toward the goal.","module":3,"topic":"M3:Setting Business Goals"},{"q":"Setting Business Goals: Why compare a proposed target with resources and the baseline?","opts":["Specific outcome","Measurable indicator","Time boundary","Feasible target"],"correct":3,"exp":"Feasibility checks whether the ambition can reasonably be pursued under actual constraints.","module":3,"topic":"M3:Setting Business Goals"},{"q":"Setting Business Goals: What is missing from a goal with no completion or review date?","opts":["Time boundary","Specific outcome","Measurable indicator","Feasible target"],"correct":0,"exp":"A time boundary establishes when progress and completion should be assessed.","module":3,"topic":"M3:Setting Business Goals"}]},
  {"key":"M3:SWOT Analysis","rows":[{"q":"SWOT Analysis: An organization has experienced technicians and reliable equipment. Which SWOT category fits?","opts":["Weakness","Opportunity","Threat","Strength"],"correct":3,"exp":"Strengths are internal capabilities that support the organization's goals.","module":3,"topic":"M3:SWOT Analysis"},{"q":"SWOT Analysis: The organization lacks an effective billing process. Which SWOT category fits?","opts":["Strength","Opportunity","Threat","Weakness"],"correct":3,"exp":"Weaknesses are internal limitations that hinder delivery or performance.","module":3,"topic":"M3:SWOT Analysis"},{"q":"SWOT Analysis: A new underserved customer segment is emerging. Which SWOT category fits?","opts":["Strength","Opportunity","Weakness","Threat"],"correct":1,"exp":"Opportunities are favorable external conditions the organization may be able to use.","module":3,"topic":"M3:SWOT Analysis"},{"q":"SWOT Analysis: A competitor plans to enter the organization's market. Which SWOT category fits?","opts":["Strength","Weakness","Threat","Opportunity"],"correct":2,"exp":"Threats are external conditions that could harm the organization's objectives.","module":3,"topic":"M3:SWOT Analysis"}]},
  {"key":"M3:PESTLE Analysis","rows":[{"q":"PESTLE Analysis: A change in government policy affects a planned business initiative. Which PESTLE category fits most directly?","opts":["Political factor","Economic factor","Technological factor","Environmental factor"],"correct":0,"exp":"Political analysis examines government priorities and policy conditions affecting the business.","module":3,"topic":"M3:PESTLE Analysis"},{"q":"PESTLE Analysis: Rising inflation changes purchasing power and costs. Which category fits?","opts":["Political factor","Economic factor","Technological factor","Environmental factor"],"correct":1,"exp":"Economic analysis examines conditions such as inflation, employment and market demand.","module":3,"topic":"M3:PESTLE Analysis"},{"q":"PESTLE Analysis: A new production technology changes how products can be delivered. Which category fits?","opts":["Technological factor","Political factor","Economic factor","Environmental factor"],"correct":0,"exp":"Technological analysis examines technical developments and their opportunities or risks.","module":3,"topic":"M3:PESTLE Analysis"},{"q":"PESTLE Analysis: Flood exposure affects the location of a distribution site. Which category fits?","opts":["Environmental factor","Political factor","Economic factor","Technological factor"],"correct":0,"exp":"Environmental analysis examines ecological conditions and physical environmental effects; legal and social factors must also be considered separately.","module":3,"topic":"M3:PESTLE Analysis"}]},
  {"key":"M3:Competitive Advantage","rows":[{"q":"Competitive Advantage: What must distinguish an offering to support a useful differentiation strategy?","opts":["Cost capability","Hard-to-copy capability","Customer-valued difference","Evidence of durability"],"correct":2,"exp":"A difference must matter to the intended customer rather than merely being unusual.","module":3,"topic":"M3:Competitive Advantage"},{"q":"Competitive Advantage: Which capability supports competing through efficient delivery at lower cost?","opts":["Customer-valued difference","Hard-to-copy capability","Cost capability","Evidence of durability"],"correct":2,"exp":"Cost capability comes from effective operations and resource use, not unsustainable price cuts alone.","module":3,"topic":"M3:Competitive Advantage"},{"q":"Competitive Advantage: What makes an advantage more difficult for competitors to imitate?","opts":["Customer-valued difference","Hard-to-copy capability","Cost capability","Evidence of durability"],"correct":1,"exp":"A distinctive system of capabilities and relationships can be harder to copy than a single feature.","module":3,"topic":"M3:Competitive Advantage"},{"q":"Competitive Advantage: What should be reviewed before claiming an advantage will last indefinitely?","opts":["Customer-valued difference","Evidence of durability","Cost capability","Hard-to-copy capability"],"correct":1,"exp":"Evidence of durability includes customer response, imitation risks and changing market conditions.","module":3,"topic":"M3:Competitive Advantage"}]},
  {"key":"M3:Business Growth Strategies","rows":[{"q":"Module 3 — Business Growth Strategies: A company sells more of its existing product to its current market. Which growth route is this?","opts":["Market development","Market penetration","Product development","Diversification"],"correct":1,"exp":"Market penetration increases activity within the existing product and market combination.","module":3,"topic":"M3:Business Growth Strategies"},{"q":"Module 3 — Business Growth Strategies: A company takes its existing service to a new customer market. Which route is this?","opts":["Market penetration","Product development","Diversification","Market development"],"correct":3,"exp":"Market development expands the market served by an existing offering.","module":3,"topic":"M3:Business Growth Strategies"},{"q":"Module 3 — Business Growth Strategies: A company creates a new product for its existing customers. Which route is this?","opts":["Market penetration","Market development","Diversification","Product development"],"correct":3,"exp":"Product development changes the offering while retaining the existing market.","module":3,"topic":"M3:Business Growth Strategies"},{"q":"Module 3 — Business Growth Strategies: A company enters a new market with a new offering. Which route is this?","opts":["Diversification","Market penetration","Market development","Product development"],"correct":0,"exp":"Diversification changes both market and product and requires careful capability and risk assessment.","module":3,"topic":"M3:Business Growth Strategies"}]},
  {"key":"M3:Strategic Decision-Making","rows":[{"q":"Strategic Decision-Making: What should be agreed before ranking strategic options?","opts":["Opportunity cost","Decision criteria","Sensitivity analysis","Documented rationale"],"correct":1,"exp":"Decision criteria connect evaluation to the organization's objectives and constraints.","module":3,"topic":"M3:Strategic Decision-Making"},{"q":"Strategic Decision-Making: What describes the value of the best alternative forgone when choosing an option?","opts":["Decision criteria","Opportunity cost","Sensitivity analysis","Documented rationale"],"correct":1,"exp":"Opportunity cost makes the trade-off between competing uses of resources explicit.","module":3,"topic":"M3:Strategic Decision-Making"},{"q":"Strategic Decision-Making: What checks whether a preferred option changes when a key assumption varies?","opts":["Decision criteria","Sensitivity analysis","Opportunity cost","Documented rationale"],"correct":1,"exp":"Sensitivity analysis reveals how much the conclusion depends on uncertain inputs.","module":3,"topic":"M3:Strategic Decision-Making"},{"q":"Strategic Decision-Making: What lets future reviewers understand why a strategic choice was made?","opts":["Decision criteria","Documented rationale","Opportunity cost","Sensitivity analysis"],"correct":1,"exp":"A documented rationale records evidence, assumptions, options and the reason for the decision.","module":3,"topic":"M3:Strategic Decision-Making"}]},
  {"key":"M3:Scenario Planning","rows":[{"q":"Scenario Planning: What should scenario planning identify when the future cannot be predicted confidently?","opts":["Coherent scenario","Trigger indicator","Critical uncertainty","Contingency response"],"correct":2,"exp":"Critical uncertainties are important factors whose different outcomes would change strategic choices.","module":3,"topic":"M3:Scenario Planning"},{"q":"Scenario Planning: What combines plausible assumptions into an internally consistent future situation?","opts":["Coherent scenario","Critical uncertainty","Trigger indicator","Contingency response"],"correct":0,"exp":"A coherent scenario is a planning aid rather than a claimed forecast.","module":3,"topic":"M3:Scenario Planning"},{"q":"Scenario Planning: What signals that an organization may need to activate a different plan?","opts":["Critical uncertainty","Trigger indicator","Coherent scenario","Contingency response"],"correct":1,"exp":"A trigger indicator links observable evidence with a review or response threshold.","module":3,"topic":"M3:Scenario Planning"},{"q":"Scenario Planning: What prepares the organization to act if an adverse scenario develops?","opts":["Critical uncertainty","Coherent scenario","Contingency response","Trigger indicator"],"correct":2,"exp":"A contingency response defines actions, ownership and resources for the relevant situation.","module":3,"topic":"M3:Scenario Planning"}]},
  {"key":"M3:Strategic Leadership Workshop","rows":[{"q":"Strategic Leadership Workshop: What should participants receive before evaluating strategic choices?","opts":["Evidence pack","Options discussion","Decision record","Action follow-up"],"correct":0,"exp":"An evidence pack provides the problem, baseline, assumptions and relevant data for informed discussion.","module":3,"topic":"M3:Strategic Leadership Workshop"},{"q":"Strategic Leadership Workshop: What workshop activity compares alternative approaches and their trade-offs?","opts":["Evidence pack","Decision record","Action follow-up","Options discussion"],"correct":3,"exp":"Options discussion examines alternatives against criteria rather than simply endorsing the loudest voice.","module":3,"topic":"M3:Strategic Leadership Workshop"},{"q":"Strategic Leadership Workshop: What should capture the approved choice, rationale and unresolved conditions?","opts":["Evidence pack","Options discussion","Decision record","Action follow-up"],"correct":2,"exp":"A decision record creates a shared reference and supports later accountability.","module":3,"topic":"M3:Strategic Leadership Workshop"},{"q":"Strategic Leadership Workshop: What turns a workshop agreement into implemented work?","opts":["Evidence pack","Options discussion","Decision record","Action follow-up"],"correct":3,"exp":"Follow-up assigns owners, dates and measures and checks completion.","module":3,"topic":"M3:Strategic Leadership Workshop"}]},
  {"key":"M4:Effective Communication","rows":[{"q":"Effective Communication: What should a communicator assess before drafting a message?","opts":["Clear message","Audience analysis","Suitable channel","Understanding check"],"correct":1,"exp":"Audience analysis considers the recipients' knowledge, needs, context and accessibility.","module":4,"topic":"M4:Effective Communication"},{"q":"Effective Communication: What helps recipients identify the requested decision or action?","opts":["Audience analysis","Suitable channel","Clear message","Understanding check"],"correct":2,"exp":"A clear message states the purpose, relevant facts and next step concisely.","module":4,"topic":"M4:Effective Communication"},{"q":"Effective Communication: What determines whether a sensitive issue should be discussed privately or in a broad email?","opts":["Suitable channel","Audience analysis","Clear message","Understanding check"],"correct":0,"exp":"Channel choice should fit sensitivity, urgency, interaction needs and confidentiality.","module":4,"topic":"M4:Effective Communication"},{"q":"Effective Communication: What confirms that recipients interpreted an instruction as intended?","opts":["Audience analysis","Clear message","Suitable channel","Understanding check"],"correct":3,"exp":"An understanding check invites questions or a summary instead of assuming that delivery proves comprehension.","module":4,"topic":"M4:Effective Communication"}]},
  {"key":"M4:Public Speaking","rows":[{"q":"Public Speaking: What should guide the selection of content for a speech?","opts":["Structured argument","Delivery practice","Question handling","Audience purpose"],"correct":3,"exp":"The audience's needs and the speaking purpose determine what information is relevant.","module":4,"topic":"M4:Public Speaking"},{"q":"Public Speaking: What helps listeners follow a speech from its opening to its conclusion?","opts":["Structured argument","Audience purpose","Delivery practice","Question handling"],"correct":0,"exp":"A structured argument connects the main claim, supporting evidence and intended action.","module":4,"topic":"M4:Public Speaking"},{"q":"Public Speaking: What improves pacing and reveals difficult sections before a live speech?","opts":["Audience purpose","Structured argument","Question handling","Delivery practice"],"correct":3,"exp":"Practice with feedback helps refine timing, clarity and delivery.","module":4,"topic":"M4:Public Speaking"},{"q":"Public Speaking: What should a speaker do when an audience question requires unverified facts?","opts":["Question handling","Audience purpose","Structured argument","Delivery practice"],"correct":0,"exp":"Acknowledge the limit, clarify the question and arrange a verified follow-up.","module":4,"topic":"M4:Public Speaking"}]},
  {"key":"M4:Business Writing","rows":[{"q":"Business Writing: What belongs near the beginning of a decision-seeking business message?","opts":["Evidence and context","Clear action request","Editing for the reader","Purpose-first opening"],"correct":3,"exp":"A purpose-first opening tells the reader what decision or outcome the message supports.","module":4,"topic":"M4:Business Writing"},{"q":"Business Writing: What allows the reader to assess a recommendation responsibly?","opts":["Purpose-first opening","Evidence and context","Clear action request","Editing for the reader"],"correct":1,"exp":"Relevant evidence and context distinguish supported conclusions from assertions.","module":4,"topic":"M4:Business Writing"},{"q":"Business Writing: What specifies who should do what and by when?","opts":["Purpose-first opening","Evidence and context","Editing for the reader","Clear action request"],"correct":3,"exp":"A clear action request makes the expected next step and deadline explicit.","module":4,"topic":"M4:Business Writing"},{"q":"Business Writing: What improves readability before sending a draft?","opts":["Editing for the reader","Purpose-first opening","Evidence and context","Clear action request"],"correct":0,"exp":"Editing removes ambiguity, unnecessary detail and errors while checking the reader's needs.","module":4,"topic":"M4:Business Writing"}]},
  {"key":"M4:Active Listening","rows":[{"q":"Active Listening: What should a leader do while a colleague explains a concern?","opts":["Clarifying question","Focused attention","Accurate paraphrase","Confirmed understanding"],"correct":1,"exp":"Focused attention limits distractions and avoids planning an interruption before hearing the point.","module":4,"topic":"M4:Active Listening"},{"q":"Active Listening: What helps resolve an unclear detail without assuming its meaning?","opts":["Clarifying question","Focused attention","Accurate paraphrase","Confirmed understanding"],"correct":0,"exp":"A clarifying question asks for the missing information in a respectful way.","module":4,"topic":"M4:Active Listening"},{"q":"Active Listening: What shows the listener's interpretation while allowing correction?","opts":["Accurate paraphrase","Focused attention","Clarifying question","Confirmed understanding"],"correct":0,"exp":"A paraphrase restates the meaning in the listener's own words.","module":4,"topic":"M4:Active Listening"},{"q":"Active Listening: What should precede acting on a complex concern?","opts":["Focused attention","Clarifying question","Accurate paraphrase","Confirmed understanding"],"correct":3,"exp":"Confirming understanding checks that the interpretation matches what the speaker intended.","module":4,"topic":"M4:Active Listening"}]},
  {"key":"M4:Giving and Receiving Feedback","rows":[{"q":"Giving and Receiving Feedback: What should constructive feedback describe instead of labeling a person's character?","opts":["Specific impact","Observed behavior","Open dialogue","Agreed next step"],"correct":1,"exp":"Observed behavior provides a specific, checkable basis for feedback.","module":4,"topic":"M4:Giving and Receiving Feedback"},{"q":"Giving and Receiving Feedback: What connects the behavior with its effect on work or people?","opts":["Observed behavior","Specific impact","Open dialogue","Agreed next step"],"correct":1,"exp":"A specific impact explains why the feedback matters without inventing motives.","module":4,"topic":"M4:Giving and Receiving Feedback"},{"q":"Giving and Receiving Feedback: What allows the recipient to add context or correct an assumption?","opts":["Observed behavior","Specific impact","Agreed next step","Open dialogue"],"correct":3,"exp":"Open dialogue treats feedback as a conversation rather than a verdict.","module":4,"topic":"M4:Giving and Receiving Feedback"},{"q":"Giving and Receiving Feedback: What makes a feedback conversation useful after it ends?","opts":["Observed behavior","Specific impact","Open dialogue","Agreed next step"],"correct":3,"exp":"An agreed next step specifies the change, support and follow-up.","module":4,"topic":"M4:Giving and Receiving Feedback"}]},
  {"key":"M4:Persuasive Communication","rows":[{"q":"Persuasive Communication: What helps a leader frame a proposal around the audience's concerns?","opts":["Support the claim","Understand interests","Address objections","Make an ethical request"],"correct":1,"exp":"Understanding interests connects the proposal to relevant needs and priorities.","module":4,"topic":"M4:Persuasive Communication"},{"q":"Persuasive Communication: What strengthens a recommendation beyond confident wording?","opts":["Understand interests","Address objections","Make an ethical request","Support the claim"],"correct":3,"exp":"Supporting evidence explains why the proposed action is credible.","module":4,"topic":"M4:Persuasive Communication"},{"q":"Persuasive Communication: What should a presenter do with a reasonable challenge to the proposal?","opts":["Understand interests","Address objections","Support the claim","Make an ethical request"],"correct":1,"exp":"Addressing objections examines alternatives and limitations instead of hiding inconvenient information.","module":4,"topic":"M4:Persuasive Communication"},{"q":"Persuasive Communication: What preserves the audience's ability to choose responsibly?","opts":["Understand interests","Make an ethical request","Support the claim","Address objections"],"correct":1,"exp":"An ethical request is truthful about costs, risks and conditions and avoids manipulative pressure.","module":4,"topic":"M4:Persuasive Communication"}]},
  {"key":"M4:Presentation Skills","rows":[{"q":"Presentation Skills: What should every slide support in a decision-oriented presentation?","opts":["Visual hierarchy","Accessible design","Rehearsed timing","Core message"],"correct":3,"exp":"A core message keeps the presentation focused on the intended decision or outcome.","module":4,"topic":"M4:Presentation Skills"},{"q":"Presentation Skills: What helps an audience see the most important content first?","opts":["Visual hierarchy","Core message","Accessible design","Rehearsed timing"],"correct":0,"exp":"Visual hierarchy uses arrangement and emphasis to guide attention.","module":4,"topic":"M4:Presentation Skills"},{"q":"Presentation Skills: What ensures that charts and text can be understood by a broader audience?","opts":["Accessible design","Core message","Visual hierarchy","Rehearsed timing"],"correct":0,"exp":"Accessible design uses readable text, sufficient contrast and explanations beyond color alone.","module":4,"topic":"M4:Presentation Skills"},{"q":"Presentation Skills: What reduces the risk of overrunning a short executive briefing?","opts":["Core message","Rehearsed timing","Visual hierarchy","Accessible design"],"correct":1,"exp":"Rehearsing timing reveals where content should be shortened or clarified.","module":4,"topic":"M4:Presentation Skills"}]},
  {"key":"M4:Executive Communication","rows":[{"q":"Executive Communication: What should a concise executive briefing state clearly at the outset?","opts":["Material evidence","Options and risks","Recommendation and next step","Decision required"],"correct":3,"exp":"The decision required tells senior readers what judgment or approval is needed.","module":4,"topic":"M4:Executive Communication"},{"q":"Executive Communication: What facts deserve priority when space is limited?","opts":["Decision required","Material evidence","Options and risks","Recommendation and next step"],"correct":1,"exp":"Material evidence is information that could reasonably affect the decision.","module":4,"topic":"M4:Executive Communication"},{"q":"Executive Communication: What prevents a briefing from presenting a recommendation as if it had no trade-offs?","opts":["Options and risks","Decision required","Material evidence","Recommendation and next step"],"correct":0,"exp":"Options and risks show alternatives, uncertainty and consequences.","module":4,"topic":"M4:Executive Communication"},{"q":"Executive Communication: What connects the briefing with a concrete action?","opts":["Decision required","Material evidence","Options and risks","Recommendation and next step"],"correct":3,"exp":"A recommendation and next step specify the proposed choice, owner and timing.","module":4,"topic":"M4:Executive Communication"}]},
  {"key":"M4:Crisis Communication","rows":[{"q":"Crisis Communication: What should a first crisis message distinguish from rumors?","opts":["Verified facts","Acknowledged uncertainty","Protective action","Scheduled update"],"correct":0,"exp":"Verified facts provide a reliable basis for public or internal communication.","module":4,"topic":"M4:Crisis Communication"},{"q":"Crisis Communication: How should the communicator treat important information that is not yet confirmed?","opts":["Verified facts","Protective action","Scheduled update","Acknowledged uncertainty"],"correct":3,"exp":"Acknowledging uncertainty avoids speculation and states what is being checked.","module":4,"topic":"M4:Crisis Communication"},{"q":"Crisis Communication: What information helps affected people respond immediately?","opts":["Verified facts","Protective action","Acknowledged uncertainty","Scheduled update"],"correct":1,"exp":"Protective action explains what people should do and where to obtain support.","module":4,"topic":"M4:Crisis Communication"},{"q":"Crisis Communication: What reduces an information vacuum as an incident develops?","opts":["Verified facts","Acknowledged uncertainty","Protective action","Scheduled update"],"correct":3,"exp":"A scheduled update identifies when and through which channel further verified information will be issued.","module":4,"topic":"M4:Crisis Communication"}]},
  {"key":"M4:Communication Practice","rows":[{"q":"Communication Practice: What should be agreed before practising a difficult business conversation?","opts":["Observer criteria","Role-play objective","Behavioral feedback","Revised attempt"],"correct":1,"exp":"A role-play objective identifies the communication skill and situation to practise.","module":4,"topic":"M4:Communication Practice"},{"q":"Communication Practice: What helps an observer assess performance consistently?","opts":["Role-play objective","Observer criteria","Behavioral feedback","Revised attempt"],"correct":1,"exp":"Observer criteria define behaviors such as clarity, listening and respectful handling of disagreement.","module":4,"topic":"M4:Communication Practice"},{"q":"Communication Practice: What should the observer provide after the exercise?","opts":["Behavioral feedback","Role-play objective","Observer criteria","Revised attempt"],"correct":0,"exp":"Behavioral feedback describes specific actions and their effects rather than general personality judgments.","module":4,"topic":"M4:Communication Practice"},{"q":"Communication Practice: What converts the feedback into a demonstrated improvement?","opts":["Role-play objective","Observer criteria","Revised attempt","Behavioral feedback"],"correct":2,"exp":"A revised attempt lets the learner apply and test the suggested change.","module":4,"topic":"M4:Communication Practice"}]},
  {"key":"M5:Building High-Performing Teams","rows":[{"q":"Building High-Performing Teams: What gives a team a common basis for prioritizing work?","opts":["Complementary roles","Psychological safety","Shared outcome","Team learning"],"correct":2,"exp":"A shared outcome defines the result the team is collectively trying to achieve.","module":5,"topic":"M5:Building High-Performing Teams"},{"q":"Building High-Performing Teams: What reduces gaps and duplicated responsibility between teammates?","opts":["Shared outcome","Complementary roles","Psychological safety","Team learning"],"correct":1,"exp":"Complementary roles combine needed capabilities with clear ownership and coordination.","module":5,"topic":"M5:Building High-Performing Teams"},{"q":"Building High-Performing Teams: What enables a colleague to report a mistake without fear of humiliation?","opts":["Shared outcome","Complementary roles","Psychological safety","Team learning"],"correct":2,"exp":"Psychological safety supports speaking up while retaining performance and conduct expectations.","module":5,"topic":"M5:Building High-Performing Teams"},{"q":"Building High-Performing Teams: What should follow a completed team milestone?","opts":["Shared outcome","Complementary roles","Psychological safety","Team learning"],"correct":3,"exp":"Team learning reviews results and cooperation to improve the next cycle.","module":5,"topic":"M5:Building High-Performing Teams"}]},
  {"key":"M5:Hiring the Right People","rows":[{"q":"Hiring the Right People: What should guide the selection criteria before candidates are assessed?","opts":["Structured evidence","Consistent comparison","Supported onboarding","Role requirements"],"correct":3,"exp":"Role requirements identify job-related capabilities and expected outcomes.","module":5,"topic":"M5:Hiring the Right People"},{"q":"Hiring the Right People: What makes an interview more useful than an informal conversation alone?","opts":["Structured evidence","Role requirements","Consistent comparison","Supported onboarding"],"correct":0,"exp":"Structured evidence uses consistent questions and relevant work samples to examine capability.","module":5,"topic":"M5:Hiring the Right People"},{"q":"Hiring the Right People: How should candidates be evaluated fairly against an agreed role?","opts":["Consistent comparison","Role requirements","Structured evidence","Supported onboarding"],"correct":0,"exp":"Consistent comparison applies the same relevant criteria and records the reasoning.","module":5,"topic":"M5:Hiring the Right People"},{"q":"Hiring the Right People: What helps a selected employee begin performing successfully?","opts":["Role requirements","Supported onboarding","Structured evidence","Consistent comparison"],"correct":1,"exp":"Onboarding supplies role clarity, necessary access, support and early feedback.","module":5,"topic":"M5:Hiring the Right People"}]},
  {"key":"M5:Delegation Skills","rows":[{"q":"Delegation Skills: What should a manager clarify before delegating a task?","opts":["Decision authority","Outcome and boundaries","Resources and support","Review checkpoints"],"correct":1,"exp":"The expected outcome and boundaries define success, constraints and acceptable scope.","module":5,"topic":"M5:Delegation Skills"},{"q":"Delegation Skills: What lets the employee know which choices they can make without another approval?","opts":["Outcome and boundaries","Decision authority","Resources and support","Review checkpoints"],"correct":1,"exp":"Decision authority specifies the discretion delegated with the work.","module":5,"topic":"M5:Delegation Skills"},{"q":"Delegation Skills: What should accompany a delegated task that requires unfamiliar equipment?","opts":["Outcome and boundaries","Decision authority","Resources and support","Review checkpoints"],"correct":2,"exp":"Resources and support make responsibility feasible rather than merely transferring pressure.","module":5,"topic":"M5:Delegation Skills"},{"q":"Delegation Skills: What supports oversight without controlling every action?","opts":["Outcome and boundaries","Decision authority","Review checkpoints","Resources and support"],"correct":2,"exp":"Agreed checkpoints review progress and risks while preserving appropriate autonomy.","module":5,"topic":"M5:Delegation Skills"}]},
  {"key":"M5:Team Motivation","rows":[{"q":"Team Motivation: What helps an employee understand why a routine task matters?","opts":["Fair recognition","Appropriate autonomy","Growth opportunity","Meaningful purpose"],"correct":3,"exp":"Meaningful purpose connects the activity with useful outcomes for stakeholders.","module":5,"topic":"M5:Team Motivation"},{"q":"Team Motivation: What supports motivation after a colleague makes a valuable contribution?","opts":["Meaningful purpose","Appropriate autonomy","Fair recognition","Growth opportunity"],"correct":2,"exp":"Fair recognition acknowledges the actual contribution consistently and specifically.","module":5,"topic":"M5:Team Motivation"},{"q":"Team Motivation: What can increase ownership for a capable employee within agreed limits?","opts":["Meaningful purpose","Fair recognition","Growth opportunity","Appropriate autonomy"],"correct":3,"exp":"Appropriate autonomy gives discretion over methods with clear expectations.","module":5,"topic":"M5:Team Motivation"},{"q":"Team Motivation: What supports long-term motivation through capability development?","opts":["Meaningful purpose","Growth opportunity","Fair recognition","Appropriate autonomy"],"correct":1,"exp":"Growth opportunities provide learning and challenge matched with support.","module":5,"topic":"M5:Team Motivation"}]},
  {"key":"M5:Employee Engagement","rows":[{"q":"Employee Engagement: What lets employees influence relevant working decisions?","opts":["Voice and participation","Role clarity","Manager support","Action on feedback"],"correct":0,"exp":"Voice and participation create meaningful opportunities to contribute rather than symbolic consultation.","module":5,"topic":"M5:Employee Engagement"},{"q":"Employee Engagement: What reduces disengagement caused by conflicting expectations?","opts":["Voice and participation","Manager support","Role clarity","Action on feedback"],"correct":2,"exp":"Role clarity explains responsibilities, priorities and how success will be evaluated.","module":5,"topic":"M5:Employee Engagement"},{"q":"Employee Engagement: What helps an employee overcome an obstacle outside their control?","opts":["Manager support","Voice and participation","Role clarity","Action on feedback"],"correct":0,"exp":"Manager support supplies coaching, resources or escalation as appropriate.","module":5,"topic":"M5:Employee Engagement"},{"q":"Employee Engagement: What should follow an engagement survey identifying an actionable problem?","opts":["Voice and participation","Action on feedback","Role clarity","Manager support"],"correct":1,"exp":"Acting on feedback and communicating progress shows that participation can affect work.","module":5,"topic":"M5:Employee Engagement"}]},
  {"key":"M5:Coaching and Mentoring","rows":[{"q":"Coaching and Mentoring: What helps a colleague reason through a challenge instead of receiving an immediate solution?","opts":["Developmental feedback","Coaching question","Mentor perspective","Learner-owned action"],"correct":1,"exp":"A coaching question invites reflection on goals, evidence, options and next steps.","module":5,"topic":"M5:Coaching and Mentoring"},{"q":"Coaching and Mentoring: What information helps the colleague identify a specific skill to improve?","opts":["Coaching question","Developmental feedback","Mentor perspective","Learner-owned action"],"correct":1,"exp":"Developmental feedback links observed behavior with an achievable improvement.","module":5,"topic":"M5:Coaching and Mentoring"},{"q":"Coaching and Mentoring: What does an experienced mentor contribute when discussing career choices?","opts":["Coaching question","Mentor perspective","Developmental feedback","Learner-owned action"],"correct":1,"exp":"A mentor offers perspective and experience while recognizing that the learner's situation may differ.","module":5,"topic":"M5:Coaching and Mentoring"},{"q":"Coaching and Mentoring: Who should own the agreed development action after the conversation?","opts":["Coaching question","Learner-owned action","Developmental feedback","Mentor perspective"],"correct":1,"exp":"Learner ownership builds responsibility; the coach or mentor provides appropriate support.","module":5,"topic":"M5:Coaching and Mentoring"}]},
  {"key":"M5:Performance Management","rows":[{"q":"Performance Management: What should be established before evaluating an employee's delivery?","opts":["Agreed expectations","Ongoing check-in","Supportive correction","Documented review"],"correct":0,"exp":"Agreed expectations define outcomes, behavior, resources and evaluation criteria.","module":5,"topic":"M5:Performance Management"},{"q":"Performance Management: What helps identify performance obstacles before a yearly review?","opts":["Agreed expectations","Supportive correction","Ongoing check-in","Documented review"],"correct":2,"exp":"Ongoing check-ins provide timely evidence and dialogue about progress.","module":5,"topic":"M5:Performance Management"},{"q":"Performance Management: What should follow a verified capability gap?","opts":["Agreed expectations","Ongoing check-in","Supportive correction","Documented review"],"correct":2,"exp":"Supportive correction clarifies the change needed and offers suitable development and resources.","module":5,"topic":"M5:Performance Management"},{"q":"Performance Management: What records outcomes and decisions for accountability?","opts":["Documented review","Agreed expectations","Ongoing check-in","Supportive correction"],"correct":0,"exp":"A documented review provides an accurate account of evidence, discussion and agreed actions.","module":5,"topic":"M5:Performance Management"}]},
  {"key":"M5:Team Conflict Resolution","rows":[{"q":"Team Conflict Resolution: What should a leader separate from personal accusations when a conflict begins?","opts":["Hear relevant perspectives","Agree working terms","Verify the resolution","Define the issue"],"correct":3,"exp":"Defining the issue focuses discussion on the behavior, decision or requirement in dispute.","module":5,"topic":"M5:Team Conflict Resolution"},{"q":"Team Conflict Resolution: What reduces the risk of deciding after hearing only one side?","opts":["Define the issue","Agree working terms","Verify the resolution","Hear relevant perspectives"],"correct":3,"exp":"Relevant perspectives provide context and enable a fair assessment of facts and interests.","module":5,"topic":"M5:Team Conflict Resolution"},{"q":"Team Conflict Resolution: What makes a resolution actionable for daily cooperation?","opts":["Agree working terms","Define the issue","Hear relevant perspectives","Verify the resolution"],"correct":0,"exp":"Working terms specify responsibilities, behavior, boundaries and follow-up.","module":5,"topic":"M5:Team Conflict Resolution"},{"q":"Team Conflict Resolution: What should a leader do after a conflict agreement is implemented?","opts":["Define the issue","Verify the resolution","Hear relevant perspectives","Agree working terms"],"correct":1,"exp":"Verify whether conduct and outcomes improved and address unresolved risks.","module":5,"topic":"M5:Team Conflict Resolution"}]},
  {"key":"M5:Remote Team Leadership","rows":[{"q":"Remote Team Leadership: What reduces confusion about expected response times across locations?","opts":["Outcome-based coordination","Communication agreement","Inclusive access","Connection and support"],"correct":1,"exp":"A communication agreement clarifies channels, availability and response expectations.","module":5,"topic":"M5:Remote Team Leadership"},{"q":"Remote Team Leadership: What should guide remote performance evaluation instead of continuous online presence?","opts":["Communication agreement","Outcome-based coordination","Inclusive access","Connection and support"],"correct":1,"exp":"Outcome-based coordination examines agreed deliverables and working conduct rather than visible activity alone.","module":5,"topic":"M5:Remote Team Leadership"},{"q":"Remote Team Leadership: What should be considered before requiring everyone to attend an online meeting?","opts":["Communication agreement","Inclusive access","Outcome-based coordination","Connection and support"],"correct":1,"exp":"Inclusive access considers time zones, connectivity, accessibility and alternatives for participation.","module":5,"topic":"M5:Remote Team Leadership"},{"q":"Remote Team Leadership: What helps prevent remote colleagues from becoming isolated?","opts":["Communication agreement","Connection and support","Outcome-based coordination","Inclusive access"],"correct":1,"exp":"Connection and support include deliberate check-ins, shared learning and access to assistance.","module":5,"topic":"M5:Remote Team Leadership"}]},
  {"key":"M6:Understanding Organizational Culture","rows":[{"q":"Understanding Organizational Culture: What describes commonly accepted ways of behaving in an organization?","opts":["Visible artifacts","Shared norms","Reward systems","Underlying assumptions"],"correct":1,"exp":"Shared norms influence what people consider expected or acceptable at work.","module":6,"topic":"M6:Understanding Organizational Culture"},{"q":"Understanding Organizational Culture: What includes office rituals, stories and symbols that may indicate culture?","opts":["Visible artifacts","Shared norms","Reward systems","Underlying assumptions"],"correct":0,"exp":"Visible artifacts offer clues but require interpretation alongside actual behavior.","module":6,"topic":"M6:Understanding Organizational Culture"},{"q":"Understanding Organizational Culture: What can reinforce a culture even when official values say something different?","opts":["Shared norms","Visible artifacts","Reward systems","Underlying assumptions"],"correct":2,"exp":"Reward systems shape behavior through what receives recognition, promotion or sanction.","module":6,"topic":"M6:Understanding Organizational Culture"},{"q":"Understanding Organizational Culture: What explains beliefs people may take for granted without openly discussing them?","opts":["Shared norms","Underlying assumptions","Visible artifacts","Reward systems"],"correct":1,"exp":"Underlying assumptions influence choices and should be tested rather than inferred from a slogan alone.","module":6,"topic":"M6:Understanding Organizational Culture"}]},
  {"key":"M6:Creating Core Values","rows":[{"q":"Creating Core Values: What helps values reflect the organization's responsibilities and lived experience?","opts":["Stakeholder input","Behavioral definition","System alignment","Conduct review"],"correct":0,"exp":"Stakeholder input gathers relevant perspectives before values are formalized.","module":6,"topic":"M6:Creating Core Values"},{"q":"Creating Core Values: What turns a value such as respect into usable guidance?","opts":["Stakeholder input","System alignment","Conduct review","Behavioral definition"],"correct":3,"exp":"Behavioral definitions describe observable actions and unacceptable conduct.","module":6,"topic":"M6:Creating Core Values"},{"q":"Creating Core Values: What prevents values from being contradicted by incentives?","opts":["System alignment","Stakeholder input","Behavioral definition","Conduct review"],"correct":0,"exp":"System alignment connects recruitment, rewards and procedures with the stated principles.","module":6,"topic":"M6:Creating Core Values"},{"q":"Creating Core Values: What establishes whether values are being practiced?","opts":["Stakeholder input","Behavioral definition","Conduct review","System alignment"],"correct":2,"exp":"Conduct review examines decisions and effects rather than merely counting displays of the values.","module":6,"topic":"M6:Creating Core Values"}]},
  {"key":"M6:Building a Positive Work Environment","rows":[{"q":"Building a Positive Work Environment: What sets a basic expectation for everyday interactions?","opts":["Respectful conduct","Clear workload expectations","Accessible support","Safe reporting"],"correct":0,"exp":"Respectful conduct protects dignity while allowing honest disagreement and feedback.","module":6,"topic":"M6:Building a Positive Work Environment"},{"q":"Building a Positive Work Environment: What reduces stress caused by hidden or competing work demands?","opts":["Clear workload expectations","Respectful conduct","Accessible support","Safe reporting"],"correct":0,"exp":"Clear workload expectations identify priorities and make capacity constraints discussable.","module":6,"topic":"M6:Building a Positive Work Environment"},{"q":"Building a Positive Work Environment: What helps staff obtain help before a work barrier becomes a larger problem?","opts":["Accessible support","Respectful conduct","Clear workload expectations","Safe reporting"],"correct":0,"exp":"Accessible support provides usable routes to guidance and resources.","module":6,"topic":"M6:Building a Positive Work Environment"},{"q":"Building a Positive Work Environment: What allows employees to raise harmful conduct appropriately?","opts":["Respectful conduct","Safe reporting","Clear workload expectations","Accessible support"],"correct":1,"exp":"Safe reporting uses clear channels and protects against retaliation in accordance with applicable rules.","module":6,"topic":"M6:Building a Positive Work Environment"}]},
  {"key":"M6:Diversity and Inclusion","rows":[{"q":"Diversity and Inclusion: Which concept examines who is present in a team or leadership group?","opts":["Inclusive participation","Representation","Equitable access","Barrier review"],"correct":1,"exp":"Representation describes composition; it does not by itself prove that people have influence.","module":6,"topic":"M6:Diversity and Inclusion"},{"q":"Diversity and Inclusion: Which practice ensures relevant voices can shape a decision?","opts":["Representation","Inclusive participation","Equitable access","Barrier review"],"correct":1,"exp":"Inclusive participation actively removes obstacles to meaningful contribution.","module":6,"topic":"M6:Diversity and Inclusion"},{"q":"Diversity and Inclusion: Which practice examines whether people can access opportunities fairly?","opts":["Representation","Equitable access","Inclusive participation","Barrier review"],"correct":1,"exp":"Equitable access considers relevant needs and barriers rather than assuming identical arrangements work for everyone.","module":6,"topic":"M6:Diversity and Inclusion"},{"q":"Diversity and Inclusion: What should a leader do when a routine process repeatedly excludes a group?","opts":["Representation","Inclusive participation","Barrier review","Equitable access"],"correct":2,"exp":"Barrier review examines the process, evidence and effects and changes unnecessary exclusion.","module":6,"topic":"M6:Diversity and Inclusion"}]},
  {"key":"M6:Employee Well-Being","rows":[{"q":"Employee Well-Being: What should a leader examine when overtime becomes a routine requirement?","opts":["Workplace safety","Workload assessment","Support access","Sustained follow-up"],"correct":1,"exp":"Workload assessment checks priorities, staffing, scheduling and achievable expectations.","module":6,"topic":"M6:Employee Well-Being"},{"q":"Employee Well-Being: What responsibility includes preventing avoidable harm from work conditions?","opts":["Workload assessment","Workplace safety","Support access","Sustained follow-up"],"correct":1,"exp":"Workplace safety requires appropriate risk controls and compliance with applicable requirements.","module":6,"topic":"M6:Employee Well-Being"},{"q":"Employee Well-Being: What helps an employee find appropriate assistance without being pressured to disclose private details publicly?","opts":["Workload assessment","Workplace safety","Support access","Sustained follow-up"],"correct":2,"exp":"Support access uses confidential, suitable channels and respects personal information.","module":6,"topic":"M6:Employee Well-Being"},{"q":"Employee Well-Being: What establishes whether a well-being initiative improved actual conditions?","opts":["Workload assessment","Sustained follow-up","Workplace safety","Support access"],"correct":1,"exp":"Sustained follow-up examines workload, experience and relevant evidence rather than attendance at an event alone.","module":6,"topic":"M6:Employee Well-Being"}]},
  {"key":"M6:Organizational Behavior","rows":[{"q":"Organizational Behavior: Which level examines a person's perceptions, motivation and work behavior?","opts":["Group dynamics","Individual factors","Organizational systems","Contextual analysis"],"correct":1,"exp":"Individual factors help explain behavior but should not be used to invent a person's motives.","module":6,"topic":"M6:Organizational Behavior"},{"q":"Organizational Behavior: Which level examines norms and interaction within a team?","opts":["Individual factors","Organizational systems","Contextual analysis","Group dynamics"],"correct":3,"exp":"Group dynamics include roles, cooperation, conflict and shared expectations.","module":6,"topic":"M6:Organizational Behavior"},{"q":"Organizational Behavior: Which level examines structures, incentives and procedures affecting conduct?","opts":["Individual factors","Group dynamics","Organizational systems","Contextual analysis"],"correct":2,"exp":"Organizational systems can enable or constrain behavior across groups.","module":6,"topic":"M6:Organizational Behavior"},{"q":"Organizational Behavior: What avoids blaming an individual before examining other causes?","opts":["Contextual analysis","Individual factors","Group dynamics","Organizational systems"],"correct":0,"exp":"Contextual analysis considers individual, group and system evidence together.","module":6,"topic":"M6:Organizational Behavior"}]},
  {"key":"M6:Culture Change","rows":[{"q":"Culture Change: What should precede launching a culture-change slogan?","opts":["Desired behaviors","Aligned reinforcement","Change evidence","Current culture diagnosis"],"correct":3,"exp":"Diagnosis examines existing norms, incentives and experiences to identify the real gap.","module":6,"topic":"M6:Culture Change"},{"q":"Culture Change: What should a desired culture specify beyond broad adjectives?","opts":["Current culture diagnosis","Aligned reinforcement","Desired behaviors","Change evidence"],"correct":2,"exp":"Desired behaviors make expectations observable and applicable to decisions.","module":6,"topic":"M6:Culture Change"},{"q":"Culture Change: What makes the new behaviors more likely to persist?","opts":["Aligned reinforcement","Current culture diagnosis","Desired behaviors","Change evidence"],"correct":0,"exp":"Aligned reinforcement connects leadership example, systems and rewards with the intended culture.","module":6,"topic":"M6:Culture Change"},{"q":"Culture Change: What shows that a culture shift has occurred?","opts":["Current culture diagnosis","Desired behaviors","Aligned reinforcement","Change evidence"],"correct":3,"exp":"Change evidence examines repeated conduct and stakeholder experience rather than announcements alone.","module":6,"topic":"M6:Culture Change"}]},
  {"key":"M6:Ethical Leadership","rows":[{"q":"Ethical Leadership: What establishes credibility when leaders ask others to follow ethical standards?","opts":["Invite concerns","Use fair decisions","Model ethical conduct","Repair harmful consequences"],"correct":2,"exp":"Leaders must demonstrate those standards in their own choices and conduct.","module":6,"topic":"M6:Ethical Leadership"},{"q":"Ethical Leadership: What helps a leader learn about an ethical problem early?","opts":["Model ethical conduct","Use fair decisions","Invite concerns","Repair harmful consequences"],"correct":2,"exp":"Inviting concerns through usable channels enables people to speak up safely.","module":6,"topic":"M6:Ethical Leadership"},{"q":"Ethical Leadership: What supports ethical judgment when scarce resources affect several groups?","opts":["Model ethical conduct","Use fair decisions","Invite concerns","Repair harmful consequences"],"correct":1,"exp":"Fair decisions use relevant criteria and examine consequences, rights and responsibilities.","module":6,"topic":"M6:Ethical Leadership"},{"q":"Ethical Leadership: What should follow discovery that a leadership decision caused avoidable harm?","opts":["Model ethical conduct","Invite concerns","Use fair decisions","Repair harmful consequences"],"correct":3,"exp":"Repair includes acknowledgment, corrective action and review of causes and controls.","module":6,"topic":"M6:Ethical Leadership"}]},
  {"key":"M7:Business Processes","rows":[{"q":"Business Processes: What enters a process before work transforms it?","opts":["Process activity","Process input","Process output","Process owner"],"correct":1,"exp":"An input is information, material or a request needed to perform the process.","module":7,"topic":"M7:Business Processes"},{"q":"Business Processes: What describes work that changes inputs into results?","opts":["Process activity","Process input","Process output","Process owner"],"correct":0,"exp":"Process activities are the steps through which value is created or delivered.","module":7,"topic":"M7:Business Processes"},{"q":"Business Processes: What should be checked against customer or user requirements at the end?","opts":["Process input","Process activity","Process owner","Process output"],"correct":3,"exp":"The output is the result delivered by the process and must be assessed for suitability.","module":7,"topic":"M7:Business Processes"},{"q":"Business Processes: Who coordinates the process and its improvement across handoffs?","opts":["Process input","Process activity","Process output","Process owner"],"correct":3,"exp":"A process owner has defined responsibility for process performance and coordination.","module":7,"topic":"M7:Business Processes"}]},
  {"key":"M7:Operational Planning","rows":[{"q":"Operational Planning: What should inform the amount of work an operating team prepares to deliver?","opts":["Capacity plan","Work schedule","Exception response","Demand estimate"],"correct":3,"exp":"A demand estimate provides an evidence-based starting point for resource planning.","module":7,"topic":"M7:Operational Planning"},{"q":"Operational Planning: What compares required work with people, equipment and time available?","opts":["Demand estimate","Work schedule","Capacity plan","Exception response"],"correct":2,"exp":"Capacity planning identifies constraints before promising delivery.","module":7,"topic":"M7:Operational Planning"},{"q":"Operational Planning: What turns planned work into sequenced assignments?","opts":["Demand estimate","Work schedule","Capacity plan","Exception response"],"correct":1,"exp":"A work schedule coordinates activities, dependencies and timing.","module":7,"topic":"M7:Operational Planning"},{"q":"Operational Planning: What prepares the team for a disruption to its operating plan?","opts":["Exception response","Demand estimate","Capacity plan","Work schedule"],"correct":0,"exp":"An exception response defines escalation, contingency actions and decision authority.","module":7,"topic":"M7:Operational Planning"}]},
  {"key":"M7:Productivity Improvement","rows":[{"q":"Productivity Improvement: What is the basic focus of productivity measurement?","opts":["Baseline measurement","Outcome per resource","Constraint diagnosis","Balanced improvement"],"correct":1,"exp":"Productivity relates useful output to resources used and must retain the meaning of quality.","module":7,"topic":"M7:Productivity Improvement"},{"q":"Productivity Improvement: What should be recorded before claiming an improvement?","opts":["Outcome per resource","Baseline measurement","Constraint diagnosis","Balanced improvement"],"correct":1,"exp":"A baseline provides a comparable starting point for evaluating change.","module":7,"topic":"M7:Productivity Improvement"},{"q":"Productivity Improvement: What identifies the cause of a persistent delivery bottleneck?","opts":["Outcome per resource","Constraint diagnosis","Baseline measurement","Balanced improvement"],"correct":1,"exp":"Constraint diagnosis examines where and why work is limited instead of pressuring every worker equally.","module":7,"topic":"M7:Productivity Improvement"},{"q":"Productivity Improvement: What prevents higher output from concealing unsafe work or falling quality?","opts":["Outcome per resource","Baseline measurement","Balanced improvement","Constraint diagnosis"],"correct":2,"exp":"Balanced improvement checks customer value, quality and people effects alongside efficiency.","module":7,"topic":"M7:Productivity Improvement"}]},
  {"key":"M7:Process Optimization","rows":[{"q":"Process Optimization: What should a team do before redesigning an unfamiliar workflow?","opts":["Identify waste","Map the flow","Test a change","Standardize a verified improvement"],"correct":1,"exp":"Mapping shows actual steps, handoffs and delays so changes address real work.","module":7,"topic":"M7:Process Optimization"},{"q":"Process Optimization: What examines unnecessary waiting, duplication or rework?","opts":["Identify waste","Map the flow","Test a change","Standardize a verified improvement"],"correct":0,"exp":"Waste identification looks for effort that does not support the required outcome.","module":7,"topic":"M7:Process Optimization"},{"q":"Process Optimization: What reduces risk before applying a change across the whole operation?","opts":["Test a change","Map the flow","Identify waste","Standardize a verified improvement"],"correct":0,"exp":"A bounded test checks effects and unintended consequences using agreed measures.","module":7,"topic":"M7:Process Optimization"},{"q":"Process Optimization: What helps preserve a successful process change?","opts":["Standardize a verified improvement","Map the flow","Identify waste","Test a change"],"correct":0,"exp":"Standardization updates procedures and training after the improvement is verified.","module":7,"topic":"M7:Process Optimization"}]},
  {"key":"M7:Resource Management","rows":[{"q":"Resource Management: What should a leader establish before promising resources to an initiative?","opts":["Priority allocation","Resource inventory","Utilization review","Capacity adjustment"],"correct":1,"exp":"An inventory clarifies available resources, constraints and existing commitments.","module":7,"topic":"M7:Resource Management"},{"q":"Resource Management: What resolves competition between projects for the same staff time?","opts":["Resource inventory","Utilization review","Priority allocation","Capacity adjustment"],"correct":2,"exp":"Priority allocation compares strategic value, urgency, dependencies and constraints.","module":7,"topic":"M7:Resource Management"},{"q":"Resource Management: What identifies an asset that is idle or overburdened?","opts":["Resource inventory","Priority allocation","Capacity adjustment","Utilization review"],"correct":3,"exp":"Utilization review compares actual use with capacity and purpose.","module":7,"topic":"M7:Resource Management"},{"q":"Resource Management: What should follow persistent demand exceeding safe available capacity?","opts":["Capacity adjustment","Resource inventory","Priority allocation","Utilization review"],"correct":0,"exp":"Capacity adjustment may change scope, sequence, staffing or equipment rather than promising impossible delivery.","module":7,"topic":"M7:Resource Management"}]},
  {"key":"M7:Supply Chain Basics","rows":[{"q":"Supply Chain Basics: What part of a supply chain provides materials or services to the organization?","opts":["Inventory position","Distribution flow","Supplier input","Supply risk"],"correct":2,"exp":"Suppliers support upstream inputs and require quality and reliability coordination.","module":7,"topic":"M7:Supply Chain Basics"},{"q":"Supply Chain Basics: What should be checked before ordering additional stock?","opts":["Supplier input","Distribution flow","Supply risk","Inventory position"],"correct":3,"exp":"Inventory position includes usable stock, commitments and expected receipts.","module":7,"topic":"M7:Supply Chain Basics"},{"q":"Supply Chain Basics: What connects completed goods with customers?","opts":["Supplier input","Distribution flow","Inventory position","Supply risk"],"correct":1,"exp":"Distribution flow organizes storage, transport and delivery downstream.","module":7,"topic":"M7:Supply Chain Basics"},{"q":"Supply Chain Basics: What should be reviewed when the business depends on a single supplier?","opts":["Supplier input","Inventory position","Distribution flow","Supply risk"],"correct":3,"exp":"Supply risk examines interruption exposure and feasible alternatives or contingency arrangements.","module":7,"topic":"M7:Supply Chain Basics"}]},
  {"key":"M7:Performance Metrics","rows":[{"q":"Performance Metrics: What prevents different teams from calculating the same metric differently?","opts":["Relevant baseline","Reporting cadence","Defined measure","Decision response"],"correct":2,"exp":"A defined measure states its formula, scope, data source and ownership.","module":7,"topic":"M7:Performance Metrics"},{"q":"Performance Metrics: What provides a meaningful comparison for a current result?","opts":["Defined measure","Relevant baseline","Reporting cadence","Decision response"],"correct":1,"exp":"A relevant baseline uses comparable periods, units and conditions.","module":7,"topic":"M7:Performance Metrics"},{"q":"Performance Metrics: What specifies when a metric will be collected and discussed?","opts":["Defined measure","Relevant baseline","Decision response","Reporting cadence"],"correct":3,"exp":"A reporting cadence matches the frequency with the decisions the measure supports.","module":7,"topic":"M7:Performance Metrics"},{"q":"Performance Metrics: What makes a metric useful after it is reported?","opts":["Defined measure","Relevant baseline","Decision response","Reporting cadence"],"correct":2,"exp":"A decision response links the result with investigation, action and follow-up where necessary.","module":7,"topic":"M7:Performance Metrics"}]},
  {"key":"M7:Operational Excellence","rows":[{"q":"Operational Excellence: What should guide operational priorities beyond internal convenience?","opts":["Customer value","Reliable processes","Continuous problem solving","People involvement"],"correct":0,"exp":"Customer value clarifies which outcomes the operation needs to deliver reliably.","module":7,"topic":"M7:Operational Excellence"},{"q":"Operational Excellence: What reduces preventable variation in repeated work?","opts":["Reliable processes","Customer value","Continuous problem solving","People involvement"],"correct":0,"exp":"Reliable processes define suitable methods, responsibilities and checks.","module":7,"topic":"M7:Operational Excellence"},{"q":"Operational Excellence: What helps an operation improve rather than repeatedly treating symptoms?","opts":["Customer value","Continuous problem solving","Reliable processes","People involvement"],"correct":1,"exp":"Continuous problem solving investigates causes, tests changes and checks results.","module":7,"topic":"M7:Operational Excellence"},{"q":"Operational Excellence: What uses practical knowledge from those doing the work?","opts":["Customer value","People involvement","Reliable processes","Continuous problem solving"],"correct":1,"exp":"People involvement enables staff to contribute evidence and improvements with clear accountability.","module":7,"topic":"M7:Operational Excellence"}]},
  {"key":"M8:Financial Literacy for Leaders","rows":[{"q":"Financial Literacy for Leaders: Which concept describes whether revenues exceed expenses over a period?","opts":["Liquidity","Financial position","Assumption review","Profitability"],"correct":3,"exp":"Profitability examines earnings and costs; it is different from available cash.","module":8,"topic":"M8:Financial Literacy for Leaders"},{"q":"Financial Literacy for Leaders: Which concept concerns meeting near-term obligations when due?","opts":["Profitability","Liquidity","Financial position","Assumption review"],"correct":1,"exp":"Liquidity depends on available cash and assets usable for obligations, not profit alone.","module":8,"topic":"M8:Financial Literacy for Leaders"},{"q":"Financial Literacy for Leaders: Which concept examines assets, liabilities and equity at a date?","opts":["Profitability","Financial position","Liquidity","Assumption review"],"correct":1,"exp":"Financial position is a snapshot of resources and claims on those resources.","module":8,"topic":"M8:Financial Literacy for Leaders"},{"q":"Financial Literacy for Leaders: What should a leader do before relying on a financial projection?","opts":["Profitability","Liquidity","Assumption review","Financial position"],"correct":2,"exp":"Review assumptions, data quality and sensitivity rather than treating estimates as guaranteed results.","module":8,"topic":"M8:Financial Literacy for Leaders"}]},
  {"key":"M8:Reading Financial Statements","rows":[{"q":"Reading Financial Statements: Which statement presents assets, liabilities and equity at a particular date?","opts":["Income statement","Cash flow statement","Statement notes","Balance sheet"],"correct":3,"exp":"A balance sheet summarizes financial position at a point in time.","module":8,"topic":"M8:Reading Financial Statements"},{"q":"Reading Financial Statements: Which statement reports revenue and expenses over a period?","opts":["Balance sheet","Income statement","Cash flow statement","Statement notes"],"correct":1,"exp":"An income statement shows earnings performance for the reporting period.","module":8,"topic":"M8:Reading Financial Statements"},{"q":"Reading Financial Statements: Which statement distinguishes operating, investing and financing cash movements?","opts":["Balance sheet","Income statement","Statement notes","Cash flow statement"],"correct":3,"exp":"A cash flow statement reports how cash changed during the period.","module":8,"topic":"M8:Reading Financial Statements"},{"q":"Reading Financial Statements: Where should a reader look for material accounting policies and supporting explanations?","opts":["Balance sheet","Statement notes","Income statement","Cash flow statement"],"correct":1,"exp":"Notes help interpret statement figures and their limitations and should be read with the statements.","module":8,"topic":"M8:Reading Financial Statements"}]},
  {"key":"M8:Budgeting","rows":[{"q":"Budgeting: What should be documented when planned sales depend on an expected demand level?","opts":["Budget assumption","Planned allocation","Variance analysis","Reforecast"],"correct":0,"exp":"A budget assumption explains the estimate so it can be reviewed when conditions change.","module":8,"topic":"M8:Budgeting"},{"q":"Budgeting: What states how approved resources will be used?","opts":["Budget assumption","Planned allocation","Variance analysis","Reforecast"],"correct":1,"exp":"Planned allocation assigns amounts to purposes and owners within the budget.","module":8,"topic":"M8:Budgeting"},{"q":"Budgeting: What compares actual spending or revenue with the approved plan?","opts":["Budget assumption","Planned allocation","Reforecast","Variance analysis"],"correct":3,"exp":"Variance analysis identifies differences and investigates their causes.","module":8,"topic":"M8:Budgeting"},{"q":"Budgeting: What updates expected results after important conditions change?","opts":["Budget assumption","Planned allocation","Reforecast","Variance analysis"],"correct":2,"exp":"A reforecast revises expectations using current evidence without hiding the original baseline.","module":8,"topic":"M8:Budgeting"}]},
  {"key":"M8:Cash Flow Management","rows":[{"q":"Cash Flow Management: What records when customers are expected to pay outstanding invoices?","opts":["Receipts schedule","Payments schedule","Cash forecast","Liquidity response"],"correct":0,"exp":"A receipts schedule considers collection timing rather than counting all sales as immediate cash.","module":8,"topic":"M8:Cash Flow Management"},{"q":"Cash Flow Management: What records when wages, suppliers and other obligations must be paid?","opts":["Receipts schedule","Cash forecast","Payments schedule","Liquidity response"],"correct":2,"exp":"A payments schedule makes cash outflow timing explicit.","module":8,"topic":"M8:Cash Flow Management"},{"q":"Cash Flow Management: What combines opening cash, expected receipts and expected payments?","opts":["Receipts schedule","Cash forecast","Payments schedule","Liquidity response"],"correct":1,"exp":"A cash forecast estimates future balances and exposes timing gaps.","module":8,"topic":"M8:Cash Flow Management"},{"q":"Cash Flow Management: A forecast shows insufficient cash before payroll. What is needed?","opts":["Receipts schedule","Payments schedule","Liquidity response","Cash forecast"],"correct":2,"exp":"A liquidity response examines verified collections, timing, authorized financing and feasible spending changes before obligations fall due.","module":8,"topic":"M8:Cash Flow Management"}]},
  {"key":"M8:Profit and Loss","rows":[{"q":"Profit and Loss: Which term describes sales amounts before deducting the associated expenses?","opts":["Revenue","Cost of sales","Gross profit","Net profit"],"correct":0,"exp":"Revenue records sales activity under the applicable accounting basis and is not automatically cash collected.","module":8,"topic":"M8:Profit and Loss"},{"q":"Profit and Loss: What term describes costs directly associated with the goods or services sold?","opts":["Revenue","Cost of sales","Gross profit","Net profit"],"correct":1,"exp":"Cost of sales is deducted from revenue to determine gross profit.","module":8,"topic":"M8:Profit and Loss"},{"q":"Profit and Loss: What is revenue minus cost of sales?","opts":["Revenue","Cost of sales","Gross profit","Net profit"],"correct":2,"exp":"Gross profit measures the margin remaining before other relevant expenses.","module":8,"topic":"M8:Profit and Loss"},{"q":"Profit and Loss: What is the remaining profit after all applicable expenses are included?","opts":["Revenue","Cost of sales","Net profit","Gross profit"],"correct":2,"exp":"Net profit differs from gross profit and must be interpreted with the reporting basis and period.","module":8,"topic":"M8:Profit and Loss"}]},
  {"key":"M8:Financial Decision-Making","rows":[{"q":"Financial Decision-Making: What financial information matters when comparing future investment options?","opts":["Risk comparison","Opportunity cost","Sensitivity test","Relevant cash effects"],"correct":3,"exp":"Relevant future cash effects help assess the consequences of the choice; already-incurred costs are treated separately.","module":8,"topic":"M8:Financial Decision-Making"},{"q":"Financial Decision-Making: What should accompany expected return when evaluating an investment?","opts":["Relevant cash effects","Risk comparison","Opportunity cost","Sensitivity test"],"correct":1,"exp":"Risk comparison considers uncertainty and possible adverse outcomes, not return alone.","module":8,"topic":"M8:Financial Decision-Making"},{"q":"Financial Decision-Making: What captures the value of using scarce funding for one project instead of another?","opts":["Opportunity cost","Relevant cash effects","Risk comparison","Sensitivity test"],"correct":0,"exp":"Opportunity cost identifies the alternative benefit forgone.","module":8,"topic":"M8:Financial Decision-Making"},{"q":"Financial Decision-Making: What checks how a decision changes if expected demand is lower?","opts":["Relevant cash effects","Sensitivity test","Risk comparison","Opportunity cost"],"correct":1,"exp":"A sensitivity test varies uncertain inputs to examine the robustness of the conclusion.","module":8,"topic":"M8:Financial Decision-Making"}]},
  {"key":"M8:Cost Control","rows":[{"q":"Cost Control: What explains why a recurring cost rises as production grows?","opts":["Spending authorization","Variance investigation","Value-preserving correction","Cost driver"],"correct":3,"exp":"A cost driver is an activity or condition that influences the cost.","module":8,"topic":"M8:Cost Control"},{"q":"Cost Control: What control establishes who may approve a purchase?","opts":["Cost driver","Variance investigation","Value-preserving correction","Spending authorization"],"correct":3,"exp":"Spending authorization defines approval rights and limits.","module":8,"topic":"M8:Cost Control"},{"q":"Cost Control: What should precede assuming that a budget overrun proves misconduct?","opts":["Variance investigation","Cost driver","Spending authorization","Value-preserving correction"],"correct":0,"exp":"Variance investigation examines timing, volume, price and other causes using evidence.","module":8,"topic":"M8:Cost Control"},{"q":"Cost Control: What should guide cost reductions in a customer-support operation?","opts":["Cost driver","Spending authorization","Value-preserving correction","Variance investigation"],"correct":2,"exp":"Value-preserving correction reduces avoidable costs while checking quality, service and people effects.","module":8,"topic":"M8:Cost Control"}]},
  {"key":"M8:Business Performance Analysis","rows":[{"q":"Business Performance Analysis: What improves the usefulness of comparing this month's results with last month's?","opts":["Ratio interpretation","Comparable trend","Nonfinancial evidence","Integrated diagnosis"],"correct":1,"exp":"Comparable trends use consistent definitions and account for relevant timing or seasonal differences.","module":8,"topic":"M8:Business Performance Analysis"},{"q":"Business Performance Analysis: What is needed before interpreting a margin ratio as good or bad?","opts":["Comparable trend","Nonfinancial evidence","Ratio interpretation","Integrated diagnosis"],"correct":2,"exp":"Ratio interpretation considers the business model, period, benchmarks and accounting context.","module":8,"topic":"M8:Business Performance Analysis"},{"q":"Business Performance Analysis: What evidence can reveal service problems that profit figures conceal?","opts":["Comparable trend","Ratio interpretation","Nonfinancial evidence","Integrated diagnosis"],"correct":2,"exp":"Nonfinancial evidence includes quality, customer experience, delivery and employee indicators.","module":8,"topic":"M8:Business Performance Analysis"},{"q":"Business Performance Analysis: What combines financial and operating evidence to explain performance?","opts":["Comparable trend","Ratio interpretation","Integrated diagnosis","Nonfinancial evidence"],"correct":2,"exp":"Integrated diagnosis examines relationships and causes instead of treating a single metric as the whole story.","module":8,"topic":"M8:Business Performance Analysis"}]},
  {"key":"M8:Financial Planning","rows":[{"q":"Financial Planning: What defines the period over which a financial plan is evaluated?","opts":["Funding requirement","Scenario model","Planning horizon","Monitoring process"],"correct":2,"exp":"A planning horizon aligns projections with the decision and investment timescale.","module":8,"topic":"M8:Financial Planning"},{"q":"Financial Planning: What estimates how much financing is needed and when?","opts":["Planning horizon","Scenario model","Monitoring process","Funding requirement"],"correct":3,"exp":"Funding requirements consider cash timing, commitments and available resources.","module":8,"topic":"M8:Financial Planning"},{"q":"Financial Planning: What examines the financial effects of different plausible conditions?","opts":["Planning horizon","Funding requirement","Monitoring process","Scenario model"],"correct":3,"exp":"Scenario models test coherent sets of assumptions rather than treating one estimate as certain.","module":8,"topic":"M8:Financial Planning"},{"q":"Financial Planning: What keeps the financial plan useful as actual results emerge?","opts":["Planning horizon","Funding requirement","Monitoring process","Scenario model"],"correct":2,"exp":"A monitoring process compares results with assumptions and triggers review or adjustment.","module":8,"topic":"M8:Financial Planning"}]},
  {"key":"M9:Marketing Fundamentals","rows":[{"q":"Marketing Fundamentals: What should guide the development of a market offering?","opts":["Customer need","Market segment","Value proposition","Marketing mix"],"correct":0,"exp":"A customer need identifies the problem or desired outcome the offering should address.","module":9,"topic":"M9:Marketing Fundamentals"},{"q":"Marketing Fundamentals: What groups customers with relevant shared characteristics or needs?","opts":["Customer need","Value proposition","Marketing mix","Market segment"],"correct":3,"exp":"A market segment helps focus research and marketing choices on a defined audience.","module":9,"topic":"M9:Marketing Fundamentals"},{"q":"Marketing Fundamentals: What explains why an intended customer should choose the offering?","opts":["Customer need","Market segment","Marketing mix","Value proposition"],"correct":3,"exp":"A value proposition connects benefits and credible differentiation with the customer's need.","module":9,"topic":"M9:Marketing Fundamentals"},{"q":"Marketing Fundamentals: What combines product, price, distribution and promotion choices?","opts":["Customer need","Marketing mix","Market segment","Value proposition"],"correct":1,"exp":"The marketing mix coordinates how the offering is developed, delivered and communicated.","module":9,"topic":"M9:Marketing Fundamentals"}]},
  {"key":"M9:Branding","rows":[{"q":"Branding: What should a brand communicate about the value customers can expect?","opts":["Brand promise","Consistent experience","Distinctive identity","Reputation evidence"],"correct":0,"exp":"A brand promise states a meaningful commitment that the organization must be able to deliver.","module":9,"topic":"M9:Branding"},{"q":"Branding: What makes a brand credible across sales and service interactions?","opts":["Brand promise","Distinctive identity","Consistent experience","Reputation evidence"],"correct":2,"exp":"Consistent experience aligns actual delivery with the promised value.","module":9,"topic":"M9:Branding"},{"q":"Branding: What helps customers recognize the brand among other offerings?","opts":["Brand promise","Consistent experience","Distinctive identity","Reputation evidence"],"correct":2,"exp":"A distinctive identity uses coherent names, visual elements and language without replacing delivery quality.","module":9,"topic":"M9:Branding"},{"q":"Branding: What should be reviewed before claiming that customers trust the brand?","opts":["Brand promise","Consistent experience","Reputation evidence","Distinctive identity"],"correct":2,"exp":"Reputation evidence includes actual customer experience and feedback rather than internal enthusiasm alone.","module":9,"topic":"M9:Branding"}]},
  {"key":"M9:Customer Experience","rows":[{"q":"Customer Experience: What traces the stages a customer passes through before and after purchase?","opts":["Friction identification","Journey mapping","Service recovery","Experience measurement"],"correct":1,"exp":"Journey mapping examines interactions from the customer's perspective.","module":9,"topic":"M9:Customer Experience"},{"q":"Customer Experience: What identifies a confusing form or repeated handoff that makes service difficult?","opts":["Friction identification","Journey mapping","Service recovery","Experience measurement"],"correct":0,"exp":"Friction identification finds obstacles that reduce the customer's ability to obtain value.","module":9,"topic":"M9:Customer Experience"},{"q":"Customer Experience: What should follow a verified service failure?","opts":["Journey mapping","Service recovery","Friction identification","Experience measurement"],"correct":1,"exp":"Service recovery acknowledges the issue, provides a suitable remedy and checks the outcome.","module":9,"topic":"M9:Customer Experience"},{"q":"Customer Experience: What shows whether an experience improvement actually helped customers?","opts":["Experience measurement","Journey mapping","Friction identification","Service recovery"],"correct":0,"exp":"Experience measurement combines relevant feedback and operating evidence across the journey.","module":9,"topic":"M9:Customer Experience"}]},
  {"key":"M9:Digital Marketing","rows":[{"q":"Digital Marketing: What should determine who a campaign is designed to reach?","opts":["Content relevance","Conversion tracking","Audience targeting","Experiment comparison"],"correct":2,"exp":"Audience targeting connects the campaign with a defined customer segment and legitimate data use.","module":9,"topic":"M9:Digital Marketing"},{"q":"Digital Marketing: What makes a campaign message useful to its intended audience?","opts":["Content relevance","Audience targeting","Conversion tracking","Experiment comparison"],"correct":0,"exp":"Relevant content addresses the customer's need and the stage of the buying journey.","module":9,"topic":"M9:Digital Marketing"},{"q":"Digital Marketing: What examines whether visits lead to an intended action?","opts":["Conversion tracking","Audience targeting","Content relevance","Experiment comparison"],"correct":0,"exp":"Conversion tracking defines the action and records an appropriate rate or count.","module":9,"topic":"M9:Digital Marketing"},{"q":"Digital Marketing: What supports choosing between two campaign messages?","opts":["Audience targeting","Content relevance","Experiment comparison","Conversion tracking"],"correct":2,"exp":"A controlled comparison uses comparable conditions and measures, while recognizing uncertainty.","module":9,"topic":"M9:Digital Marketing"}]},
  {"key":"M9:Sales Leadership","rows":[{"q":"Sales Leadership: What distinguishes a plausible sales prospect from an unexamined contact?","opts":["Sales coaching","Qualified opportunity","Pipeline review","Ethical commitment"],"correct":1,"exp":"A qualified opportunity has evidence of relevant need, fit and a feasible purchasing process.","module":9,"topic":"M9:Sales Leadership"},{"q":"Sales Leadership: What helps a salesperson improve a specific conversation skill?","opts":["Qualified opportunity","Sales coaching","Pipeline review","Ethical commitment"],"correct":1,"exp":"Sales coaching uses observed evidence, practice and feedback rather than quotas alone.","module":9,"topic":"M9:Sales Leadership"},{"q":"Sales Leadership: What helps forecast progress across stages of active opportunities?","opts":["Qualified opportunity","Pipeline review","Sales coaching","Ethical commitment"],"correct":1,"exp":"Pipeline review checks stage definitions, evidence and next actions without treating every lead as a certain sale.","module":9,"topic":"M9:Sales Leadership"},{"q":"Sales Leadership: What should a sales leader enforce when a tempting deal requires an unsupported promise?","opts":["Qualified opportunity","Sales coaching","Ethical commitment","Pipeline review"],"correct":2,"exp":"Ethical commitment means promising only what can responsibly be delivered and making conditions clear.","module":9,"topic":"M9:Sales Leadership"}]},
  {"key":"M9:Customer Relationship Management","rows":[{"q":"Customer Relationship Management: What should be corrected when a customer's contact and order details are wrong?","opts":["Relevant follow-up","Accurate customer record","Consent and access control","Relationship analysis"],"correct":1,"exp":"Accurate records support useful service and prevent decisions based on incorrect information.","module":9,"topic":"M9:Customer Relationship Management"},{"q":"Customer Relationship Management: What maintains a useful relationship after a customer inquiry?","opts":["Accurate customer record","Consent and access control","Relevant follow-up","Relationship analysis"],"correct":2,"exp":"Relevant follow-up addresses the customer's actual need and agreed next step.","module":9,"topic":"M9:Customer Relationship Management"},{"q":"Customer Relationship Management: What should govern collection and use of personal customer information?","opts":["Accurate customer record","Consent and access control","Relevant follow-up","Relationship analysis"],"correct":1,"exp":"Consent where required and appropriate access control support responsible data handling under applicable rules.","module":9,"topic":"M9:Customer Relationship Management"},{"q":"Customer Relationship Management: What can reveal recurring service issues across customer interactions?","opts":["Accurate customer record","Relevant follow-up","Relationship analysis","Consent and access control"],"correct":2,"exp":"Relationship analysis examines reliable records and patterns to guide improvement.","module":9,"topic":"M9:Customer Relationship Management"}]},
  {"key":"M9:Market Positioning","rows":[{"q":"Market Positioning: What should positioning identify before making a broad claim of superiority?","opts":["Frame of reference","Target customer","Point of difference","Supporting proof"],"correct":1,"exp":"A target customer defines whose needs and alternatives the positioning concerns.","module":9,"topic":"M9:Market Positioning"},{"q":"Market Positioning: What helps customers understand the category or alternatives against which an offering is compared?","opts":["Target customer","Point of difference","Supporting proof","Frame of reference"],"correct":3,"exp":"A frame of reference supplies the comparison context for the claim.","module":9,"topic":"M9:Market Positioning"},{"q":"Market Positioning: What identifies the meaningful benefit that distinguishes the offering?","opts":["Target customer","Frame of reference","Point of difference","Supporting proof"],"correct":2,"exp":"A point of difference must matter to the target customer and be deliverable.","module":9,"topic":"M9:Market Positioning"},{"q":"Market Positioning: What should substantiate a positioning claim?","opts":["Target customer","Frame of reference","Point of difference","Supporting proof"],"correct":3,"exp":"Supporting proof gives credible evidence rather than relying only on a slogan.","module":9,"topic":"M9:Market Positioning"}]},
  {"key":"M9:Business Growth Strategies","rows":[{"q":"Module 9 — Business Growth Strategies: A campaign seeks first purchases from suitable new customers. Which marketing growth lever is used?","opts":["Retention","Customer expansion","Acquisition","Channel partnership"],"correct":2,"exp":"Acquisition attracts relevant new customers and must be assessed against cost and conversion.","module":9,"topic":"M9:Business Growth Strategies"},{"q":"Module 9 — Business Growth Strategies: A business improves renewal service for existing customers. Which lever is used?","opts":["Acquisition","Retention","Customer expansion","Channel partnership"],"correct":1,"exp":"Retention aims to preserve useful relationships by sustaining customer value.","module":9,"topic":"M9:Business Growth Strategies"},{"q":"Module 9 — Business Growth Strategies: A satisfied customer adopts an additional suitable service. Which lever is used?","opts":["Acquisition","Retention","Channel partnership","Customer expansion"],"correct":3,"exp":"Customer expansion grows a relationship through relevant additional value rather than pressured sales.","module":9,"topic":"M9:Business Growth Strategies"},{"q":"Module 9 — Business Growth Strategies: A reseller helps a business reach customers it cannot efficiently serve directly. Which lever is used?","opts":["Channel partnership","Acquisition","Retention","Customer expansion"],"correct":0,"exp":"A channel partnership extends access through agreed roles, incentives and service standards.","module":9,"topic":"M9:Business Growth Strategies"}]},
  {"key":"M10:Innovation in Business","rows":[{"q":"Innovation in Business: What should innovation investigate before committing to a proposed solution?","opts":["Problem discovery","Idea generation","Prototype test","Validated adoption"],"correct":0,"exp":"Problem discovery checks that a meaningful customer or operating need exists.","module":10,"topic":"M10:Innovation in Business"},{"q":"Innovation in Business: What develops alternative ways to address the identified need?","opts":["Idea generation","Problem discovery","Prototype test","Validated adoption"],"correct":0,"exp":"Idea generation broadens possible solutions before the team selects and tests one.","module":10,"topic":"M10:Innovation in Business"},{"q":"Innovation in Business: What allows a business to learn about a proposed solution with limited exposure?","opts":["Prototype test","Problem discovery","Idea generation","Validated adoption"],"correct":0,"exp":"A prototype test uses a bounded representation or pilot to gather evidence.","module":10,"topic":"M10:Innovation in Business"},{"q":"Innovation in Business: What should guide expansion after a promising experiment?","opts":["Validated adoption","Problem discovery","Idea generation","Prototype test"],"correct":0,"exp":"Validated adoption checks value, feasibility, resources and risks before scaling.","module":10,"topic":"M10:Innovation in Business"}]},
  {"key":"M10:Creative Thinking","rows":[{"q":"Creative Thinking: What can uncover possibilities hidden by a familiar way of working?","opts":["Generate alternatives","Question an assumption","Combine perspectives","Evaluate ideas"],"correct":1,"exp":"Questioning an assumption asks whether a taken-for-granted constraint is necessary.","module":10,"topic":"M10:Creative Thinking"},{"q":"Creative Thinking: What should a team do before choosing the first plausible solution?","opts":["Question an assumption","Combine perspectives","Evaluate ideas","Generate alternatives"],"correct":3,"exp":"Generating alternatives expands the options available for later evaluation.","module":10,"topic":"M10:Creative Thinking"},{"q":"Creative Thinking: What can reveal a solution missed by a group with identical experiences?","opts":["Question an assumption","Combine perspectives","Generate alternatives","Evaluate ideas"],"correct":1,"exp":"Combining perspectives introduces different knowledge and interpretations.","module":10,"topic":"M10:Creative Thinking"},{"q":"Creative Thinking: What should follow divergent idea generation?","opts":["Question an assumption","Generate alternatives","Combine perspectives","Evaluate ideas"],"correct":3,"exp":"Evaluation compares ideas with the problem, evidence, criteria and constraints.","module":10,"topic":"M10:Creative Thinking"}]},
  {"key":"M10:Managing Change","rows":[{"q":"Managing Change: What explains why the current approach needs to change?","opts":["Change rationale","Stakeholder impact","Transition support","Adoption review"],"correct":0,"exp":"A change rationale connects evidence and desired outcomes with the need for action.","module":10,"topic":"M10:Managing Change"},{"q":"Managing Change: What should be assessed before changing a work process?","opts":["Change rationale","Transition support","Stakeholder impact","Adoption review"],"correct":2,"exp":"Stakeholder impact examines how responsibilities, skills and conditions will be affected.","module":10,"topic":"M10:Managing Change"},{"q":"Managing Change: What helps employees work effectively during a transition?","opts":["Change rationale","Stakeholder impact","Transition support","Adoption review"],"correct":2,"exp":"Transition support provides communication, training, resources and routes for help.","module":10,"topic":"M10:Managing Change"},{"q":"Managing Change: What shows whether the change is being used effectively?","opts":["Change rationale","Stakeholder impact","Transition support","Adoption review"],"correct":3,"exp":"Adoption review examines actual behavior and outcomes rather than announcement or attendance counts alone.","module":10,"topic":"M10:Managing Change"}]},
  {"key":"M10:Digital Transformation","rows":[{"q":"Module 10 — Digital Transformation: What should drive a change initiative involving digital technology?","opts":["Business outcome","Process redesign","People readiness","Benefits realization"],"correct":0,"exp":"A business outcome defines the value sought rather than treating tool installation as success.","module":10,"topic":"M10:Digital Transformation"},{"q":"Module 10 — Digital Transformation: What may be required when software is applied to an ineffective workflow?","opts":["Business outcome","People readiness","Benefits realization","Process redesign"],"correct":3,"exp":"Process redesign addresses underlying work instead of merely digitizing the same problems.","module":10,"topic":"M10:Digital Transformation"},{"q":"Module 10 — Digital Transformation: What should be checked before expecting employees to adopt new tools?","opts":["Business outcome","Process redesign","People readiness","Benefits realization"],"correct":2,"exp":"People readiness includes skills, access, workload and support for the new way of working.","module":10,"topic":"M10:Digital Transformation"},{"q":"Module 10 — Digital Transformation: What confirms whether the digital change delivered its intended value?","opts":["Business outcome","Process redesign","People readiness","Benefits realization"],"correct":3,"exp":"Benefits realization compares observed results with the expected outcomes and adjusts the initiative.","module":10,"topic":"M10:Digital Transformation"}]},
  {"key":"M10:Business Process Innovation","rows":[{"q":"Business Process Innovation: What should a process innovation address?","opts":["New process design","Pilot evidence","Scaling readiness","Customer problem"],"correct":3,"exp":"A customer or operating problem provides a reason to design a meaningfully different process.","module":10,"topic":"M10:Business Process Innovation"},{"q":"Business Process Innovation: What changes the way value is created rather than only making one existing step faster?","opts":["Customer problem","Pilot evidence","Scaling readiness","New process design"],"correct":3,"exp":"A new process design may alter roles, sequence, technology or delivery logic.","module":10,"topic":"M10:Business Process Innovation"},{"q":"Business Process Innovation: What should support approval to expand a redesigned process?","opts":["Customer problem","New process design","Pilot evidence","Scaling readiness"],"correct":2,"exp":"Pilot evidence checks outcomes and unintended effects under defined conditions.","module":10,"topic":"M10:Business Process Innovation"},{"q":"Business Process Innovation: What should be assessed before rolling the new process out broadly?","opts":["Scaling readiness","Customer problem","New process design","Pilot evidence"],"correct":0,"exp":"Scaling readiness includes capacity, controls, training, integration and accountable ownership.","module":10,"topic":"M10:Business Process Innovation"}]},
  {"key":"M10:Leading Organizational Change","rows":[{"q":"Leading Organizational Change: What demonstrates that senior leadership accepts responsibility for a change?","opts":["Visible sponsorship","Change coalition","Local enablement","Sustained reinforcement"],"correct":0,"exp":"Visible sponsorship supplies direction, decisions and resources rather than symbolic endorsement alone.","module":10,"topic":"M10:Leading Organizational Change"},{"q":"Leading Organizational Change: What brings relevant leaders and stakeholders together to coordinate the change?","opts":["Visible sponsorship","Local enablement","Change coalition","Sustained reinforcement"],"correct":2,"exp":"A change coalition combines influence and expertise with clear responsibilities.","module":10,"topic":"M10:Leading Organizational Change"},{"q":"Leading Organizational Change: What helps individual teams implement a broad change in their own context?","opts":["Visible sponsorship","Change coalition","Local enablement","Sustained reinforcement"],"correct":2,"exp":"Local enablement translates direction into usable training, support and role clarity.","module":10,"topic":"M10:Leading Organizational Change"},{"q":"Leading Organizational Change: What prevents employees from reverting when old incentives remain?","opts":["Sustained reinforcement","Visible sponsorship","Change coalition","Local enablement"],"correct":0,"exp":"Sustained reinforcement aligns systems, measures and leadership conduct with the new approach.","module":10,"topic":"M10:Leading Organizational Change"}]},
  {"key":"M10:Managing Resistance","rows":[{"q":"Managing Resistance: What should precede labeling a colleague resistant to change?","opts":["Distinguish the barrier","Understand the concern","Offer a proportionate response","Check changed behavior"],"correct":1,"exp":"Understanding the concern may reveal a valid risk, missing information or practical obstacle.","module":10,"topic":"M10:Managing Resistance"},{"q":"Managing Resistance: What separates a skill gap from disagreement about the change's purpose?","opts":["Distinguish the barrier","Understand the concern","Offer a proportionate response","Check changed behavior"],"correct":0,"exp":"Barrier diagnosis identifies the type of issue so the response can fit it.","module":10,"topic":"M10:Managing Resistance"},{"q":"Managing Resistance: What should a leader do after discovering that staff lack required system access?","opts":["Offer a proportionate response","Understand the concern","Distinguish the barrier","Check changed behavior"],"correct":0,"exp":"A proportionate response removes the access barrier instead of treating it as a motivation problem.","module":10,"topic":"M10:Managing Resistance"},{"q":"Managing Resistance: What shows whether the response reduced the actual obstacle?","opts":["Check changed behavior","Understand the concern","Distinguish the barrier","Offer a proportionate response"],"correct":0,"exp":"Checking behavior and outcomes verifies the effect rather than assuming acceptance from silence.","module":10,"topic":"M10:Managing Resistance"}]},
  {"key":"M10:Continuous Improvement","rows":[{"q":"Module 10 — Continuous Improvement: Which stage defines the problem, hypothesis and intended measures in a small improvement cycle?","opts":["Plan","Do","Check","Act"],"correct":0,"exp":"Planning makes the test and expected result explicit before implementation.","module":10,"topic":"M10:Continuous Improvement"},{"q":"Module 10 — Continuous Improvement: Which stage carries out the agreed bounded test?","opts":["Plan","Check","Do","Act"],"correct":2,"exp":"Doing implements the test while collecting relevant observations.","module":10,"topic":"M10:Continuous Improvement"},{"q":"Module 10 — Continuous Improvement: Which stage compares observed results with the hypothesis?","opts":["Check","Plan","Do","Act"],"correct":0,"exp":"Checking examines evidence, including unintended effects, before drawing a conclusion.","module":10,"topic":"M10:Continuous Improvement"},{"q":"Module 10 — Continuous Improvement: Which stage standardizes a verified improvement or revises the next test?","opts":["Plan","Do","Act","Check"],"correct":2,"exp":"Acting uses the learning to update practice or begin another cycle.","module":10,"topic":"M10:Continuous Improvement"}]},
  {"key":"M11:Negotiation Skills","rows":[{"q":"Negotiation Skills: What explains why a party wants a particular outcome?","opts":["BATNA","Reservation point","Interests","Possible agreement zone"],"correct":2,"exp":"Interests are underlying needs or concerns, while positions are stated demands.","module":11,"topic":"M11:Negotiation Skills"},{"q":"Negotiation Skills: What is the best feasible alternative if no agreement is reached?","opts":["Interests","BATNA","Reservation point","Possible agreement zone"],"correct":1,"exp":"BATNA provides a comparison for evaluating a proposed negotiated agreement.","module":11,"topic":"M11:Negotiation Skills"},{"q":"Negotiation Skills: What sets a party's acceptable limit for the deal?","opts":["Reservation point","Interests","BATNA","Possible agreement zone"],"correct":0,"exp":"A reservation point defines the boundary beyond which the alternative is preferable.","module":11,"topic":"M11:Negotiation Skills"},{"q":"Negotiation Skills: What describes the overlap between parties' acceptable deal ranges?","opts":["Interests","Possible agreement zone","BATNA","Reservation point"],"correct":1,"exp":"A possible agreement zone exists where both parties can accept the terms, subject to other conditions.","module":11,"topic":"M11:Negotiation Skills"}]},
  {"key":"M11:Business Negotiation Strategies","rows":[{"q":"Business Negotiation Strategies: What should guide preparation before a supplier negotiation?","opts":["Explore interests","Prepare criteria","Trade across issues","Document agreement"],"correct":1,"exp":"Criteria include goals, constraints, alternatives and relevant evidence for evaluating terms.","module":11,"topic":"M11:Business Negotiation Strategies"},{"q":"Business Negotiation Strategies: What can reveal that the supplier values payment timing more than a small price change?","opts":["Prepare criteria","Explore interests","Trade across issues","Document agreement"],"correct":1,"exp":"Exploring interests identifies preferences that stated positions may conceal.","module":11,"topic":"M11:Business Negotiation Strategies"},{"q":"Business Negotiation Strategies: What can create value when parties prioritize different issues?","opts":["Trade across issues","Prepare criteria","Explore interests","Document agreement"],"correct":0,"exp":"Trading across issues allows concessions on less important terms in exchange for valued ones.","module":11,"topic":"M11:Business Negotiation Strategies"},{"q":"Business Negotiation Strategies: What reduces later disagreement about an accepted deal?","opts":["Prepare criteria","Explore interests","Trade across issues","Document agreement"],"correct":3,"exp":"A documented agreement states obligations, timing, conditions and any required approvals.","module":11,"topic":"M11:Business Negotiation Strategies"}]},
  {"key":"M11:Conflict Resolution","rows":[{"q":"Conflict Resolution: What should be stated before proposing a resolution?","opts":["Separate facts and interpretations","Identify the disagreement","Compare workable options","Agree follow-up"],"correct":1,"exp":"Identify the specific issue and parties rather than treating the conflict as a personality label.","module":11,"topic":"M11:Conflict Resolution"},{"q":"Conflict Resolution: What reduces misunderstanding when accounts of an event differ?","opts":["Separate facts and interpretations","Identify the disagreement","Compare workable options","Agree follow-up"],"correct":0,"exp":"Separating facts and interpretations makes uncertain claims visible for verification.","module":11,"topic":"M11:Conflict Resolution"},{"q":"Conflict Resolution: What helps parties find an acceptable response to the issue?","opts":["Identify the disagreement","Separate facts and interpretations","Agree follow-up","Compare workable options"],"correct":3,"exp":"Workable options are evaluated against interests, rights, feasibility and responsibilities.","module":11,"topic":"M11:Conflict Resolution"},{"q":"Conflict Resolution: What helps ensure that a resolution is implemented?","opts":["Agree follow-up","Identify the disagreement","Separate facts and interpretations","Compare workable options"],"correct":0,"exp":"Follow-up records responsibilities and reviews the effect of the agreement.","module":11,"topic":"M11:Conflict Resolution"}]},
  {"key":"M11:Mediation Techniques","rows":[{"q":"Mediation Techniques: What distinguishes a mediator's role from deciding which party should win?","opts":["Neutral facilitation","Voluntary participation where appropriate","Interest exploration","Agreed record"],"correct":0,"exp":"Neutral facilitation supports a fair discussion; the mediator does not impose a judgment merely by mediating.","module":11,"topic":"M11:Mediation Techniques"},{"q":"Mediation Techniques: What should be considered before using mediation in a workplace dispute?","opts":["Neutral facilitation","Voluntary participation where appropriate","Interest exploration","Agreed record"],"correct":1,"exp":"Participation conditions and suitability must be assessed; serious allegations may require a formal process instead.","module":11,"topic":"M11:Mediation Techniques"},{"q":"Mediation Techniques: What helps parties move beyond fixed demands?","opts":["Neutral facilitation","Voluntary participation where appropriate","Interest exploration","Agreed record"],"correct":2,"exp":"Interest exploration examines needs and concerns to develop acceptable options.","module":11,"topic":"M11:Mediation Techniques"},{"q":"Mediation Techniques: What should be prepared when parties reach a suitable settlement?","opts":["Neutral facilitation","Voluntary participation where appropriate","Agreed record","Interest exploration"],"correct":2,"exp":"An agreed record states terms, responsibilities and review arrangements within the applicable process.","module":11,"topic":"M11:Mediation Techniques"}]},
  {"key":"M11:Handling Difficult Conversations","rows":[{"q":"Handling Difficult Conversations: What should a leader do before discussing a sensitive performance concern?","opts":["Behavior-based opening","Private preparation","Listening to context","Clear next step"],"correct":1,"exp":"Preparation verifies facts, considers the purpose and selects a suitable confidential setting.","module":11,"topic":"M11:Handling Difficult Conversations"},{"q":"Handling Difficult Conversations: How should the leader introduce the concern constructively?","opts":["Private preparation","Listening to context","Clear next step","Behavior-based opening"],"correct":3,"exp":"A behavior-based opening describes specific observations and effects without inventing motives.","module":11,"topic":"M11:Handling Difficult Conversations"},{"q":"Handling Difficult Conversations: What should happen before finalizing a conclusion about the issue?","opts":["Listening to context","Private preparation","Behavior-based opening","Clear next step"],"correct":0,"exp":"Listening allows relevant context and correction of mistaken assumptions.","module":11,"topic":"M11:Handling Difficult Conversations"},{"q":"Handling Difficult Conversations: What should end the conversation so expectations are usable?","opts":["Private preparation","Behavior-based opening","Listening to context","Clear next step"],"correct":3,"exp":"A clear next step specifies action, support, ownership and follow-up.","module":11,"topic":"M11:Handling Difficult Conversations"}]},
  {"key":"M11:Workplace Disputes","rows":[{"q":"Workplace Disputes: What should guide the route used to address a workplace complaint?","opts":["Impartial fact-finding","Applicable procedure","Confidential handling","Protection from retaliation"],"correct":1,"exp":"The applicable procedure defines responsibilities and must be checked against current local requirements.","module":11,"topic":"M11:Workplace Disputes"},{"q":"Workplace Disputes: What should precede a conclusion when accounts of misconduct conflict?","opts":["Applicable procedure","Confidential handling","Protection from retaliation","Impartial fact-finding"],"correct":3,"exp":"Impartial fact-finding assesses relevant evidence and gives appropriate opportunities to respond.","module":11,"topic":"M11:Workplace Disputes"},{"q":"Workplace Disputes: What protects sensitive information during a dispute process?","opts":["Applicable procedure","Impartial fact-finding","Confidential handling","Protection from retaliation"],"correct":2,"exp":"Confidential handling restricts sharing to appropriate authorized purposes, without promising absolute secrecy.","module":11,"topic":"M11:Workplace Disputes"},{"q":"Workplace Disputes: What helps employees raise concerns without fear of punitive treatment?","opts":["Applicable procedure","Protection from retaliation","Impartial fact-finding","Confidential handling"],"correct":1,"exp":"Protection from retaliation supports reporting and must be implemented under applicable rules.","module":11,"topic":"M11:Workplace Disputes"}]},
  {"key":"M11:Win-Win Solutions","rows":[{"q":"Win-Win Solutions: What can help parties discover value they both want?","opts":["Shared interest","Multiple options","Objective criteria","Implementation feasibility"],"correct":0,"exp":"A shared interest provides a basis for cooperation even when other interests differ.","module":11,"topic":"M11:Win-Win Solutions"},{"q":"Win-Win Solutions: What should parties generate before treating a dispute as a single fixed choice?","opts":["Multiple options","Shared interest","Objective criteria","Implementation feasibility"],"correct":0,"exp":"Multiple options may reveal different combinations that better satisfy legitimate interests.","module":11,"topic":"M11:Win-Win Solutions"},{"q":"Win-Win Solutions: What can help evaluate proposed terms without relying only on power?","opts":["Objective criteria","Shared interest","Multiple options","Implementation feasibility"],"correct":0,"exp":"Objective criteria provide relevant standards and evidence for the discussion.","module":11,"topic":"M11:Win-Win Solutions"},{"q":"Win-Win Solutions: What should be checked before calling an agreement mutually beneficial?","opts":["Shared interest","Multiple options","Implementation feasibility","Objective criteria"],"correct":2,"exp":"Implementation feasibility includes resources, obligations and likely consequences for all affected parties.","module":11,"topic":"M11:Win-Win Solutions"}]},
  {"key":"M11:Negotiation Practice","rows":[{"q":"Negotiation Practice: What should a learner prepare before simulating a negotiation?","opts":["Role-play exchange","Preparation brief","Observer evidence","Negotiation reflection"],"correct":1,"exp":"A preparation brief records interests, objectives, alternatives, limits and possible trades.","module":11,"topic":"M11:Negotiation Practice"},{"q":"Negotiation Practice: What tests whether the learner can listen and respond under pressure?","opts":["Preparation brief","Observer evidence","Negotiation reflection","Role-play exchange"],"correct":3,"exp":"A role-play exchange creates a bounded opportunity to apply negotiation behaviors.","module":11,"topic":"M11:Negotiation Practice"},{"q":"Negotiation Practice: What should support feedback after the simulation?","opts":["Preparation brief","Observer evidence","Role-play exchange","Negotiation reflection"],"correct":1,"exp":"Observer evidence records specific actions, questions and effects instead of general impressions.","module":11,"topic":"M11:Negotiation Practice"},{"q":"Negotiation Practice: What should the learner examine after reviewing the result?","opts":["Preparation brief","Role-play exchange","Negotiation reflection","Observer evidence"],"correct":2,"exp":"Reflection considers both the agreement and the process, including missed information and ethical choices.","module":11,"topic":"M11:Negotiation Practice"}]},
  {"key":"M12:Human Resource Fundamentals","rows":[{"q":"Human Resource Fundamentals: What aligns staffing requirements with business priorities?","opts":["Fair employment practices","Employee development","People information stewardship","Workforce planning"],"correct":3,"exp":"Workforce planning examines demand, capabilities and available capacity.","module":12,"topic":"M12:Human Resource Fundamentals"},{"q":"Human Resource Fundamentals: What should guide consistent treatment throughout the employee lifecycle?","opts":["Fair employment practices","Workforce planning","Employee development","People information stewardship"],"correct":0,"exp":"Fair employment practices use relevant criteria and respect applicable employment requirements.","module":12,"topic":"M12:Human Resource Fundamentals"},{"q":"Human Resource Fundamentals: What builds capability after recruitment?","opts":["Workforce planning","Fair employment practices","People information stewardship","Employee development"],"correct":3,"exp":"Development provides learning, feedback and appropriate opportunities to practise.","module":12,"topic":"M12:Human Resource Fundamentals"},{"q":"Human Resource Fundamentals: What responsibility applies to records containing personal employee information?","opts":["Workforce planning","People information stewardship","Fair employment practices","Employee development"],"correct":1,"exp":"People information stewardship requires accurate records, appropriate access and responsible handling.","module":12,"topic":"M12:Human Resource Fundamentals"}]},
  {"key":"M12:Recruitment Strategies","rows":[{"q":"Recruitment Strategies: What should be established before advertising a vacancy?","opts":["Suitable sourcing","Structured selection","Selection review","Job-related criteria"],"correct":3,"exp":"Job-related criteria define the capabilities and outcomes actually required for the role.","module":12,"topic":"M12:Recruitment Strategies"},{"q":"Recruitment Strategies: What helps reach relevant applicants without unnecessarily excluding qualified groups?","opts":["Job-related criteria","Suitable sourcing","Structured selection","Selection review"],"correct":1,"exp":"Suitable sourcing chooses accessible channels matched with the role and candidate market.","module":12,"topic":"M12:Recruitment Strategies"},{"q":"Recruitment Strategies: What improves comparability between candidates?","opts":["Job-related criteria","Suitable sourcing","Selection review","Structured selection"],"correct":3,"exp":"Structured selection applies consistent relevant questions, evidence and assessment criteria.","module":12,"topic":"M12:Recruitment Strategies"},{"q":"Recruitment Strategies: What checks whether the recruitment approach produced fair and useful results?","opts":["Job-related criteria","Suitable sourcing","Selection review","Structured selection"],"correct":2,"exp":"Selection review examines evidence, outcomes and potential barriers for future improvement.","module":12,"topic":"M12:Recruitment Strategies"}]},
  {"key":"M12:Talent Management","rows":[{"q":"Talent Management: What reveals the skills available and gaps that matter to the business?","opts":["Development pathway","Retention diagnosis","Deployment planning","Capability identification"],"correct":3,"exp":"Capability identification connects workforce evidence with current and future needs.","module":12,"topic":"M12:Talent Management"},{"q":"Talent Management: What helps an employee progress toward a needed capability?","opts":["Capability identification","Development pathway","Retention diagnosis","Deployment planning"],"correct":1,"exp":"A development pathway combines relevant learning, experience and feedback.","module":12,"topic":"M12:Talent Management"},{"q":"Talent Management: What should a leader examine before assuming pay is the only reason for turnover?","opts":["Retention diagnosis","Capability identification","Development pathway","Deployment planning"],"correct":0,"exp":"Retention diagnosis considers workload, support, opportunity, fairness and other evidence.","module":12,"topic":"M12:Talent Management"},{"q":"Talent Management: What aligns people's capabilities with suitable assignments?","opts":["Deployment planning","Capability identification","Development pathway","Retention diagnosis"],"correct":0,"exp":"Deployment planning balances business needs, employee development and realistic capacity.","module":12,"topic":"M12:Talent Management"}]},
  {"key":"M12:Employee Development","rows":[{"q":"Employee Development: What should define the purpose of an employee's training?","opts":["Relevant learning activity","Supported application","Development need","Transfer review"],"correct":2,"exp":"A development need identifies the capability gap and its relationship to work.","module":12,"topic":"M12:Employee Development"},{"q":"Employee Development: What should be selected after the need is understood?","opts":["Relevant learning activity","Development need","Supported application","Transfer review"],"correct":0,"exp":"A relevant activity is matched with the capability rather than chosen for popularity alone.","module":12,"topic":"M12:Employee Development"},{"q":"Employee Development: What enables a trainee to use a newly learned skill at work?","opts":["Development need","Relevant learning activity","Supported application","Transfer review"],"correct":2,"exp":"Supported application provides opportunity, resources and feedback in the real role.","module":12,"topic":"M12:Employee Development"},{"q":"Employee Development: What shows whether training improved work performance?","opts":["Development need","Relevant learning activity","Supported application","Transfer review"],"correct":3,"exp":"Transfer review examines application and outcomes instead of attendance alone.","module":12,"topic":"M12:Employee Development"}]},
  {"key":"M12:Succession Planning","rows":[{"q":"Succession Planning: What should succession planning identify before naming potential replacements?","opts":["Readiness evidence","Development experience","Critical role","Continuity contingency"],"correct":2,"exp":"Critical roles are positions whose loss would materially affect organizational continuity.","module":12,"topic":"M12:Succession Planning"},{"q":"Succession Planning: What should support a judgment that a candidate can take on the role?","opts":["Critical role","Development experience","Readiness evidence","Continuity contingency"],"correct":2,"exp":"Readiness evidence includes demonstrated capability and remaining gaps rather than tenure alone.","module":12,"topic":"M12:Succession Planning"},{"q":"Succession Planning: What helps a potential successor build missing capability?","opts":["Development experience","Critical role","Readiness evidence","Continuity contingency"],"correct":0,"exp":"Development experiences provide relevant assignments and support before a transition is required.","module":12,"topic":"M12:Succession Planning"},{"q":"Succession Planning: What prepares the organization if a key employee leaves unexpectedly?","opts":["Critical role","Continuity contingency","Readiness evidence","Development experience"],"correct":1,"exp":"A continuity contingency covers interim authority, essential knowledge and immediate responsibilities.","module":12,"topic":"M12:Succession Planning"}]},
  {"key":"M12:Performance Reviews","rows":[{"q":"Module 12 — Performance Reviews: What should a formal review assess against?","opts":["Agreed role criteria","Balanced evidence","Development conversation","Documented agreement"],"correct":0,"exp":"Agreed role criteria provide a relevant and consistent basis for evaluation.","module":12,"topic":"M12:Performance Reviews"},{"q":"Module 12 — Performance Reviews: What reduces the risk that one recent incident dominates the review?","opts":["Balanced evidence","Agreed role criteria","Development conversation","Documented agreement"],"correct":0,"exp":"Balanced evidence covers the review period and examines outcomes and conduct.","module":12,"topic":"M12:Performance Reviews"},{"q":"Module 12 — Performance Reviews: What supports improvement rather than only delivering a rating?","opts":["Agreed role criteria","Development conversation","Balanced evidence","Documented agreement"],"correct":1,"exp":"A development conversation identifies strengths, barriers and practical learning priorities.","module":12,"topic":"M12:Performance Reviews"},{"q":"Module 12 — Performance Reviews: What should capture the review's agreed goals and support?","opts":["Agreed role criteria","Balanced evidence","Development conversation","Documented agreement"],"correct":3,"exp":"A documented agreement records expectations, resources and follow-up while allowing appropriate correction.","module":12,"topic":"M12:Performance Reviews"}]},
  {"key":"M12:Compensation & Benefits","rows":[{"q":"Compensation & Benefits: What establishes consistent pay ranges for comparable work?","opts":["Total reward","Internal fairness","Applicable obligations","Role-related pay structure"],"correct":3,"exp":"A role-related structure considers job demands and relevant market context under applicable rules.","module":12,"topic":"M12:Compensation & Benefits"},{"q":"Compensation & Benefits: What includes salary alongside other financial and nonfinancial rewards?","opts":["Role-related pay structure","Internal fairness","Total reward","Applicable obligations"],"correct":2,"exp":"Total reward considers benefits, development and other appropriate elements of the employee offering.","module":12,"topic":"M12:Compensation & Benefits"},{"q":"Compensation & Benefits: What should be reviewed when similar roles receive unexplained different treatment?","opts":["Role-related pay structure","Internal fairness","Total reward","Applicable obligations"],"correct":1,"exp":"Internal fairness examines relevant criteria and unjustified disparities without assuming every difference is improper.","module":12,"topic":"M12:Compensation & Benefits"},{"q":"Compensation & Benefits: What must be verified before implementing a pay or benefits policy?","opts":["Role-related pay structure","Applicable obligations","Total reward","Internal fairness"],"correct":1,"exp":"Applicable obligations vary by jurisdiction, contract and policy and require current authoritative checks.","module":12,"topic":"M12:Compensation & Benefits"}]},
  {"key":"M12:Employment Law Basics","rows":[{"q":"Employment Law Basics: What should a leader check before making a decision about dismissal or leave?","opts":["Fair procedure","Accurate documentation","Current local requirements","Qualified advice"],"correct":2,"exp":"Employment requirements depend on jurisdiction and the facts; a course example is not a substitute for current rules.","module":12,"topic":"M12:Employment Law Basics"},{"q":"Employment Law Basics: What helps ensure an affected employee is treated appropriately during a formal process?","opts":["Current local requirements","Fair procedure","Accurate documentation","Qualified advice"],"correct":1,"exp":"Fair procedure follows applicable requirements and provides the appropriate opportunity to be heard.","module":12,"topic":"M12:Employment Law Basics"},{"q":"Employment Law Basics: What supports later review of an employment decision?","opts":["Current local requirements","Accurate documentation","Fair procedure","Qualified advice"],"correct":1,"exp":"Accurate documentation records facts, reasoning and process without inventing evidence.","module":12,"topic":"M12:Employment Law Basics"},{"q":"Employment Law Basics: What should a leader seek when the legal implications of a decision are unclear?","opts":["Qualified advice","Current local requirements","Fair procedure","Accurate documentation"],"correct":0,"exp":"Qualified HR or legal advice helps establish the applicable requirements before acting.","module":12,"topic":"M12:Employment Law Basics"}]},
  {"key":"M13:Goal Setting","rows":[{"q":"Goal Setting: What should a goal state rather than merely list activity?","opts":["Aligned priority","Outcome definition","Progress measure","Review commitment"],"correct":1,"exp":"An outcome definition describes the useful result that the activity should produce.","module":13,"topic":"M13:Goal Setting"},{"q":"Goal Setting: What prevents a project goal from competing unnecessarily with organizational direction?","opts":["Outcome definition","Progress measure","Aligned priority","Review commitment"],"correct":2,"exp":"An aligned priority connects the project's outcome with agreed business objectives.","module":13,"topic":"M13:Goal Setting"},{"q":"Goal Setting: What indicates movement toward the intended result?","opts":["Outcome definition","Progress measure","Aligned priority","Review commitment"],"correct":1,"exp":"A progress measure gives a defined basis for judging improvement or completion.","module":13,"topic":"M13:Goal Setting"},{"q":"Goal Setting: What ensures that a goal is revisited as evidence changes?","opts":["Outcome definition","Review commitment","Aligned priority","Progress measure"],"correct":1,"exp":"A review commitment specifies when progress, assumptions and needed adjustments will be discussed.","module":13,"topic":"M13:Goal Setting"}]},
  {"key":"M13:Key Performance Indicators (KPIs)","rows":[{"q":"Key Performance Indicators (KPIs): What makes a measure a useful key performance indicator rather than just an available number?","opts":["Defined calculation","Strategic relevance","Leading indicator","Lagging indicator"],"correct":1,"exp":"Strategic relevance connects the measure with an important objective and decision.","module":13,"topic":"M13:Key Performance Indicators (KPIs)"},{"q":"Key Performance Indicators (KPIs): What prevents different reports from using incompatible versions of a KPI?","opts":["Defined calculation","Strategic relevance","Leading indicator","Lagging indicator"],"correct":0,"exp":"A defined calculation states formula, unit, scope, data source and reporting rules.","module":13,"topic":"M13:Key Performance Indicators (KPIs)"},{"q":"Key Performance Indicators (KPIs): Which type of indicator tracks a factor expected to influence a later outcome?","opts":["Strategic relevance","Leading indicator","Defined calculation","Lagging indicator"],"correct":1,"exp":"A leading indicator can provide early signals, but the assumed relationship must be tested.","module":13,"topic":"M13:Key Performance Indicators (KPIs)"},{"q":"Key Performance Indicators (KPIs): Which type records an outcome after the relevant activity has occurred?","opts":["Strategic relevance","Lagging indicator","Defined calculation","Leading indicator"],"correct":1,"exp":"A lagging indicator summarizes results such as completed sales or recorded defects.","module":13,"topic":"M13:Key Performance Indicators (KPIs)"}]},
  {"key":"M13:Project Planning","rows":[{"q":"Project Planning: What identifies what a project includes and excludes?","opts":["Work breakdown","Scope boundary","Dependency sequence","Risk response"],"correct":1,"exp":"A scope boundary reduces ambiguity about the agreed deliverable and change requirements.","module":13,"topic":"M13:Project Planning"},{"q":"Project Planning: What divides a deliverable into manageable pieces of work?","opts":["Scope boundary","Dependency sequence","Work breakdown","Risk response"],"correct":2,"exp":"A work breakdown organizes tasks or components so ownership and estimates can be developed.","module":13,"topic":"M13:Project Planning"},{"q":"Project Planning: What should be examined before assigning every task the same start date?","opts":["Dependency sequence","Scope boundary","Work breakdown","Risk response"],"correct":0,"exp":"Dependencies identify work that requires another task or input to be completed first.","module":13,"topic":"M13:Project Planning"},{"q":"Project Planning: What prepares the project for an identified uncertain event?","opts":["Scope boundary","Risk response","Work breakdown","Dependency sequence"],"correct":1,"exp":"A risk response specifies mitigation, contingency, ownership and monitoring where appropriate.","module":13,"topic":"M13:Project Planning"}]},
  {"key":"M13:Monitoring Performance","rows":[{"q":"Monitoring Performance: What is required before trusting a progress dashboard?","opts":["Comparison with plan","Reliable status data","Cause investigation","Corrective decision"],"correct":1,"exp":"Status data must use consistent definitions and be checked for accuracy and completeness.","module":13,"topic":"M13:Monitoring Performance"},{"q":"Monitoring Performance: What identifies whether actual delivery differs from the expected milestone?","opts":["Reliable status data","Cause investigation","Comparison with plan","Corrective decision"],"correct":2,"exp":"Comparison with the plan reveals deviations using the agreed baseline.","module":13,"topic":"M13:Monitoring Performance"},{"q":"Monitoring Performance: What should precede choosing an action for a missed target?","opts":["Reliable status data","Comparison with plan","Cause investigation","Corrective decision"],"correct":2,"exp":"Cause investigation examines relevant evidence rather than assuming poor effort.","module":13,"topic":"M13:Monitoring Performance"},{"q":"Monitoring Performance: What should follow a verified issue requiring intervention?","opts":["Reliable status data","Comparison with plan","Cause investigation","Corrective decision"],"correct":3,"exp":"A corrective decision assigns action, responsibility and a check on whether the intervention works.","module":13,"topic":"M13:Monitoring Performance"}]},
  {"key":"M13:Time Management","rows":[{"q":"Time Management: What should determine which task receives attention first?","opts":["Protected focus","Realistic scheduling","Priority judgment","Commitment review"],"correct":2,"exp":"Priority judgment weighs value, urgency, dependencies and responsibilities rather than message order alone.","module":13,"topic":"M13:Time Management"},{"q":"Time Management: What reduces avoidable interruptions during demanding work?","opts":["Priority judgment","Realistic scheduling","Commitment review","Protected focus"],"correct":3,"exp":"Protected focus uses suitable boundaries and agreed communication expectations.","module":13,"topic":"M13:Time Management"},{"q":"Time Management: What should account for preparation, dependencies and available capacity?","opts":["Priority judgment","Realistic scheduling","Protected focus","Commitment review"],"correct":1,"exp":"Realistic scheduling avoids promising more work than the available time can support.","module":13,"topic":"M13:Time Management"},{"q":"Time Management: What should happen when new urgent work makes an earlier deadline infeasible?","opts":["Priority judgment","Protected focus","Realistic scheduling","Commitment review"],"correct":3,"exp":"Commitment review communicates the conflict and renegotiates priorities or resources appropriately.","module":13,"topic":"M13:Time Management"}]},
  {"key":"M13:Productivity Systems","rows":[{"q":"Productivity Systems: What prevents new tasks from being lost across messages and meetings?","opts":["Organize commitments","Execute priorities","Capture work","Review the system"],"correct":2,"exp":"Capturing work creates a reliable record before commitments are forgotten.","module":13,"topic":"M13:Productivity Systems"},{"q":"Productivity Systems: What clarifies which recorded items are actions, waiting items or future ideas?","opts":["Capture work","Execute priorities","Organize commitments","Review the system"],"correct":2,"exp":"Organizing commitments separates work by the next decision or action required.","module":13,"topic":"M13:Productivity Systems"},{"q":"Productivity Systems: What turns a task list into useful delivery?","opts":["Capture work","Organize commitments","Execute priorities","Review the system"],"correct":2,"exp":"Executing priorities focuses effort on the work that best supports agreed outcomes.","module":13,"topic":"M13:Productivity Systems"},{"q":"Productivity Systems: What identifies whether a productivity method is creating unnecessary administration?","opts":["Capture work","Organize commitments","Review the system","Execute priorities"],"correct":2,"exp":"System review checks reliability and useful results and removes unhelpful complexity.","module":13,"topic":"M13:Productivity Systems"}]},
  {"key":"M13:Performance Reviews","rows":[{"q":"Module 13 — Performance Reviews: What should a project performance review compare results against?","opts":["Project result criteria","Milestone evidence","Lessons from variance","Future delivery improvement"],"correct":0,"exp":"Project result criteria include agreed deliverables, quality, timing and stakeholder outcomes.","module":13,"topic":"M13:Performance Reviews"},{"q":"Module 13 — Performance Reviews: What should support statements about how delivery progressed?","opts":["Project result criteria","Lessons from variance","Milestone evidence","Future delivery improvement"],"correct":2,"exp":"Milestone evidence documents actual dates, outputs and verified status across the project.","module":13,"topic":"M13:Performance Reviews"},{"q":"Module 13 — Performance Reviews: What should a team examine when actual results differ from the baseline?","opts":["Project result criteria","Milestone evidence","Future delivery improvement","Lessons from variance"],"correct":3,"exp":"Lessons from variance identify contributing causes and distinguish controllable factors from context.","module":13,"topic":"M13:Performance Reviews"},{"q":"Module 13 — Performance Reviews: What should a performance review produce for the next project?","opts":["Project result criteria","Future delivery improvement","Milestone evidence","Lessons from variance"],"correct":1,"exp":"Future improvement identifies changes to planning, coordination or controls with clear ownership.","module":13,"topic":"M13:Performance Reviews"}]},
  {"key":"M13:Continuous Improvement","rows":[{"q":"Module 13 — Continuous Improvement: What organizes potential changes discovered through project reviews?","opts":["Prioritized experiment","Outcome check","Shared learning","Improvement backlog"],"correct":3,"exp":"An improvement backlog records candidate changes and the evidence behind them.","module":13,"topic":"M13:Continuous Improvement"},{"q":"Module 13 — Continuous Improvement: What turns one promising idea into a manageable test?","opts":["Improvement backlog","Outcome check","Shared learning","Prioritized experiment"],"correct":3,"exp":"A prioritized experiment specifies a hypothesis, scope, owner and measures.","module":13,"topic":"M13:Continuous Improvement"},{"q":"Module 13 — Continuous Improvement: What should be examined before extending the tested change?","opts":["Outcome check","Improvement backlog","Prioritized experiment","Shared learning"],"correct":0,"exp":"An outcome check compares useful results and unintended effects with expectations.","module":13,"topic":"M13:Continuous Improvement"},{"q":"Module 13 — Continuous Improvement: What lets other teams benefit from a completed experiment?","opts":["Improvement backlog","Shared learning","Prioritized experiment","Outcome check"],"correct":1,"exp":"Shared learning records the context, evidence and limitations as well as the conclusion.","module":13,"topic":"M13:Continuous Improvement"}]},
  {"key":"M14:Entrepreneurial Leadership","rows":[{"q":"Entrepreneurial Leadership: What identifies an unmet need worth investigating?","opts":["Resourcefulness","Calculated experimentation","Opportunity discovery","Responsible ownership"],"correct":2,"exp":"Opportunity discovery examines real customer problems rather than assuming enthusiasm proves demand.","module":14,"topic":"M14:Entrepreneurial Leadership"},{"q":"Entrepreneurial Leadership: What helps a founder make progress with constrained resources?","opts":["Opportunity discovery","Calculated experimentation","Responsible ownership","Resourcefulness"],"correct":3,"exp":"Resourcefulness combines available capabilities and relationships without ignoring constraints or obligations.","module":14,"topic":"M14:Entrepreneurial Leadership"},{"q":"Entrepreneurial Leadership: What allows a founder to test an uncertain opportunity before a large commitment?","opts":["Opportunity discovery","Resourcefulness","Responsible ownership","Calculated experimentation"],"correct":3,"exp":"Calculated experimentation limits exposure and uses evidence to decide the next step.","module":14,"topic":"M14:Entrepreneurial Leadership"},{"q":"Entrepreneurial Leadership: What should a founder demonstrate when a fast decision affects employees and customers?","opts":["Opportunity discovery","Resourcefulness","Responsible ownership","Calculated experimentation"],"correct":2,"exp":"Responsible ownership considers consequences, communicates honestly and accepts accountability.","module":14,"topic":"M14:Entrepreneurial Leadership"}]},
  {"key":"M14:Business Model Innovation","rows":[{"q":"Business Model Innovation: What part of a business model explains the benefit provided to customers?","opts":["Value delivery","Value capture","Value creation","Model validation"],"correct":2,"exp":"Value creation connects activities and capabilities with a meaningful customer outcome.","module":14,"topic":"M14:Business Model Innovation"},{"q":"Business Model Innovation: What part explains how the benefit reaches the customer?","opts":["Value creation","Value capture","Model validation","Value delivery"],"correct":3,"exp":"Value delivery describes channels, relationships and operating arrangements.","module":14,"topic":"M14:Business Model Innovation"},{"q":"Business Model Innovation: What part explains how the business earns enough to sustain the offering?","opts":["Value creation","Value capture","Value delivery","Model validation"],"correct":1,"exp":"Value capture considers revenue mechanisms and costs rather than customer popularity alone.","module":14,"topic":"M14:Business Model Innovation"},{"q":"Business Model Innovation: What should precede claiming that a redesigned business model is viable?","opts":["Value creation","Model validation","Value delivery","Value capture"],"correct":1,"exp":"Model validation tests demand, delivery feasibility and financial assumptions with evidence.","module":14,"topic":"M14:Business Model Innovation"}]},
  {"key":"M14:Scaling a Business","rows":[{"q":"Scaling a Business: What should be established before rapidly expanding a service?","opts":["Repeatable delivery","Capacity readiness","Control maturity","Unit economics"],"correct":0,"exp":"Repeatable delivery means the service can consistently meet requirements beyond a single founder's effort.","module":14,"topic":"M14:Scaling a Business"},{"q":"Scaling a Business: What checks whether people, systems and suppliers can support greater demand?","opts":["Repeatable delivery","Capacity readiness","Control maturity","Unit economics"],"correct":1,"exp":"Capacity readiness identifies constraints that growth may expose.","module":14,"topic":"M14:Scaling a Business"},{"q":"Scaling a Business: What helps prevent growth from weakening accountability and quality?","opts":["Repeatable delivery","Control maturity","Capacity readiness","Unit economics"],"correct":1,"exp":"Control maturity provides proportionate ownership, checks and escalation as complexity increases.","module":14,"topic":"M14:Scaling a Business"},{"q":"Scaling a Business: What should be reviewed if every additional sale increases losses?","opts":["Repeatable delivery","Capacity readiness","Control maturity","Unit economics"],"correct":3,"exp":"Unit economics examines contribution and costs at an appropriate unit level before expanding volume.","module":14,"topic":"M14:Scaling a Business"}]},
  {"key":"M14:Business Expansion","rows":[{"q":"Business Expansion: What should support a proposed move into another region?","opts":["Market evidence","Entry approach","Resource commitment","Expansion review"],"correct":0,"exp":"Market evidence examines local demand, alternatives, access and relevant requirements.","module":14,"topic":"M14:Business Expansion"},{"q":"Business Expansion: What determines whether to enter through a direct operation, partner or another suitable route?","opts":["Market evidence","Resource commitment","Entry approach","Expansion review"],"correct":2,"exp":"An entry approach compares control, cost, capability and risk for the context.","module":14,"topic":"M14:Business Expansion"},{"q":"Business Expansion: What should be planned before opening the new operation?","opts":["Market evidence","Entry approach","Expansion review","Resource commitment"],"correct":3,"exp":"Resource commitment covers funding, people, systems and feasible delivery capacity.","module":14,"topic":"M14:Business Expansion"},{"q":"Business Expansion: What establishes whether the expansion should continue or change?","opts":["Market evidence","Entry approach","Resource commitment","Expansion review"],"correct":3,"exp":"Expansion review compares actual performance and assumptions with agreed milestones and thresholds.","module":14,"topic":"M14:Business Expansion"}]},
  {"key":"M14:Strategic Partnerships","rows":[{"q":"Strategic Partnerships: What provides a useful reason for forming a partnership?","opts":["Complementary value","Partner due diligence","Governance agreement","Relationship review"],"correct":0,"exp":"Complementary value means the parties contribute capabilities that support a shared purpose.","module":14,"topic":"M14:Strategic Partnerships"},{"q":"Strategic Partnerships: What should a business examine before relying on a prospective partner?","opts":["Complementary value","Partner due diligence","Governance agreement","Relationship review"],"correct":1,"exp":"Due diligence checks relevant capability, conduct, commitments and risks.","module":14,"topic":"M14:Strategic Partnerships"},{"q":"Strategic Partnerships: What should clarify decision rights, obligations and dispute routes?","opts":["Complementary value","Partner due diligence","Relationship review","Governance agreement"],"correct":3,"exp":"A governance agreement makes partnership responsibilities and boundaries explicit.","module":14,"topic":"M14:Strategic Partnerships"},{"q":"Strategic Partnerships: What checks whether the partnership remains useful and trustworthy?","opts":["Complementary value","Partner due diligence","Governance agreement","Relationship review"],"correct":3,"exp":"Relationship review examines delivery, communication, risk and continued alignment.","module":14,"topic":"M14:Strategic Partnerships"}]},
  {"key":"M14:Investment Readiness","rows":[{"q":"Investment Readiness: What supports an investor-facing claim that a business has traction?","opts":["Credible business evidence","Financial assumptions","Risk disclosure","Funding use plan"],"correct":0,"exp":"Credible evidence includes verified customer, operating or revenue results with clear definitions.","module":14,"topic":"M14:Investment Readiness"},{"q":"Investment Readiness: What should accompany a projected growth figure?","opts":["Financial assumptions","Credible business evidence","Risk disclosure","Funding use plan"],"correct":0,"exp":"Financial assumptions show how the projection was developed and where uncertainty remains.","module":14,"topic":"M14:Investment Readiness"},{"q":"Investment Readiness: What allows a potential funder to assess adverse outcomes responsibly?","opts":["Credible business evidence","Risk disclosure","Financial assumptions","Funding use plan"],"correct":1,"exp":"Risk disclosure communicates material uncertainty and limitations without promising guaranteed returns.","module":14,"topic":"M14:Investment Readiness"},{"q":"Investment Readiness: What should explain the purpose of the requested financing?","opts":["Credible business evidence","Funding use plan","Financial assumptions","Risk disclosure"],"correct":1,"exp":"A funding use plan connects amounts and timing with milestones and accountable use of resources.","module":14,"topic":"M14:Investment Readiness"}]},
  {"key":"M14:Corporate Entrepreneurship","rows":[{"q":"Corporate Entrepreneurship: What starts a new venture initiative inside an established organization?","opts":["Internal opportunity","Executive sponsor","Bounded venture test","Integration decision"],"correct":0,"exp":"An internal opportunity identifies potential value aligned with the organization's capabilities and purpose.","module":14,"topic":"M14:Corporate Entrepreneurship"},{"q":"Corporate Entrepreneurship: What helps the initiative obtain authorized resources and resolve organizational barriers?","opts":["Internal opportunity","Executive sponsor","Bounded venture test","Integration decision"],"correct":1,"exp":"An executive sponsor supplies appropriate authority and support without replacing evidence-based review.","module":14,"topic":"M14:Corporate Entrepreneurship"},{"q":"Corporate Entrepreneurship: What reduces exposure while the venture's assumptions are uncertain?","opts":["Internal opportunity","Executive sponsor","Bounded venture test","Integration decision"],"correct":2,"exp":"A bounded test uses limits and learning goals before larger commitments.","module":14,"topic":"M14:Corporate Entrepreneurship"},{"q":"Corporate Entrepreneurship: What should follow validated results from an internal venture pilot?","opts":["Internal opportunity","Executive sponsor","Bounded venture test","Integration decision"],"correct":3,"exp":"An integration decision considers whether to scale, adapt, separate or stop the initiative based on evidence.","module":14,"topic":"M14:Corporate Entrepreneurship"}]},
  {"key":"M14:Sustainable Growth","rows":[{"q":"Sustainable Growth: What avoids defining growth only by increasing sales?","opts":["Balanced outcomes","Resource resilience","Stakeholder responsibility","Long-term review"],"correct":0,"exp":"Balanced outcomes consider financial viability, service quality, people and other relevant effects.","module":14,"topic":"M14:Sustainable Growth"},{"q":"Sustainable Growth: What helps a growing business withstand interruptions?","opts":["Balanced outcomes","Stakeholder responsibility","Resource resilience","Long-term review"],"correct":2,"exp":"Resource resilience examines capacity, cash, suppliers and feasible contingency arrangements.","module":14,"topic":"M14:Sustainable Growth"},{"q":"Sustainable Growth: What considers the effects of growth on workers, communities and customers?","opts":["Balanced outcomes","Resource resilience","Long-term review","Stakeholder responsibility"],"correct":3,"exp":"Stakeholder responsibility incorporates affected interests into decisions and accountability.","module":14,"topic":"M14:Sustainable Growth"},{"q":"Sustainable Growth: What tests whether short-term gains undermine future viability?","opts":["Balanced outcomes","Resource resilience","Long-term review","Stakeholder responsibility"],"correct":2,"exp":"Long-term review examines durable value, dependencies and consequences over an appropriate horizon.","module":14,"topic":"M14:Sustainable Growth"}]},
  {"key":"M15:Digital Transformation","rows":[{"q":"Module 15 — Digital Transformation: What establishes decision rights and accountability for business technology investments?","opts":["System integration","Information quality","Technology governance","Adoption capability"],"correct":2,"exp":"Technology governance connects choices, risks and oversight with organizational priorities.","module":15,"topic":"M15:Digital Transformation"},{"q":"Module 15 — Digital Transformation: What should be checked when a new platform must exchange data with existing tools?","opts":["Technology governance","System integration","Information quality","Adoption capability"],"correct":1,"exp":"System integration examines compatible processes, interfaces and ownership across the technology environment.","module":15,"topic":"M15:Digital Transformation"},{"q":"Module 15 — Digital Transformation: What affects whether a digital dashboard supports sound business decisions?","opts":["Technology governance","System integration","Adoption capability","Information quality"],"correct":3,"exp":"Information quality includes accuracy, completeness, relevance and appropriate timeliness.","module":15,"topic":"M15:Digital Transformation"},{"q":"Module 15 — Digital Transformation: What enables staff to use a digital platform effectively in their actual roles?","opts":["Adoption capability","Technology governance","System integration","Information quality"],"correct":0,"exp":"Adoption capability combines skills, access, practical workflow and ongoing support.","module":15,"topic":"M15:Digital Transformation"}]},
  {"key":"M15:Artificial Intelligence in Business","rows":[{"q":"Artificial Intelligence in Business: What should a leader define before procuring an AI system?","opts":["Representative evaluation","Human accountability","Ongoing risk monitoring","Use-case definition"],"correct":3,"exp":"The use case specifies intended outcomes, context, users, constraints and potential harms.","module":15,"topic":"M15:Artificial Intelligence in Business"},{"q":"Artificial Intelligence in Business: What is required before trusting an AI tool on important business decisions?","opts":["Representative evaluation","Use-case definition","Human accountability","Ongoing risk monitoring"],"correct":0,"exp":"Representative evaluation checks performance and failure modes on relevant data and conditions.","module":15,"topic":"M15:Artificial Intelligence in Business"},{"q":"Artificial Intelligence in Business: Who remains responsible for a decision made using an AI recommendation?","opts":["Use-case definition","Representative evaluation","Human accountability","Ongoing risk monitoring"],"correct":2,"exp":"Human accountability assigns authorized people responsibility for judgment and consequences rather than treating the tool as an accountable actor.","module":15,"topic":"M15:Artificial Intelligence in Business"},{"q":"Artificial Intelligence in Business: What should continue after an AI system is deployed?","opts":["Use-case definition","Representative evaluation","Ongoing risk monitoring","Human accountability"],"correct":2,"exp":"Risk monitoring checks changing data, performance, unintended effects and suitable escalation.","module":15,"topic":"M15:Artificial Intelligence in Business"}]},
  {"key":"M15:Data-Driven Decision Making","rows":[{"q":"Data-Driven Decision Making: What should guide selection of data for analysis?","opts":["Relevant data","Interpretation limits","Decision validation","Decision question"],"correct":3,"exp":"A decision question identifies the judgment the evidence needs to inform.","module":15,"topic":"M15:Data-Driven Decision Making"},{"q":"Data-Driven Decision Making: What should be examined before using a dataset?","opts":["Relevant data","Decision question","Interpretation limits","Decision validation"],"correct":0,"exp":"Relevant data must be suitable, reliable and appropriately collected for the intended purpose.","module":15,"topic":"M15:Data-Driven Decision Making"},{"q":"Data-Driven Decision Making: What should a leader remember when two measures move together?","opts":["Interpretation limits","Decision question","Relevant data","Decision validation"],"correct":0,"exp":"Interpretation limits include the distinction between correlation and causation and possible alternative explanations.","module":15,"topic":"M15:Data-Driven Decision Making"},{"q":"Data-Driven Decision Making: What should follow acting on an analytical recommendation?","opts":["Decision validation","Decision question","Relevant data","Interpretation limits"],"correct":0,"exp":"Decision validation examines real outcomes and whether the original reasoning held up.","module":15,"topic":"M15:Data-Driven Decision Making"}]},
  {"key":"M15:Business Intelligence","rows":[{"q":"Business Intelligence: What should be agreed before teams build competing reports?","opts":["Defined business measure","Data pipeline","Dashboard design","Actionable insight"],"correct":0,"exp":"A defined measure establishes consistent meaning, calculation and source.","module":15,"topic":"M15:Business Intelligence"},{"q":"Business Intelligence: What moves and transforms source data into a reportable form?","opts":["Defined business measure","Data pipeline","Dashboard design","Actionable insight"],"correct":1,"exp":"A data pipeline needs appropriate quality checks and responsibility for processing.","module":15,"topic":"M15:Business Intelligence"},{"q":"Business Intelligence: What should make important comparisons and limitations visible to users?","opts":["Defined business measure","Data pipeline","Actionable insight","Dashboard design"],"correct":3,"exp":"Dashboard design supports interpretation through clear labels, relevant context and readable presentation.","module":15,"topic":"M15:Business Intelligence"},{"q":"Business Intelligence: What makes a report valuable beyond displaying numbers?","opts":["Defined business measure","Data pipeline","Actionable insight","Dashboard design"],"correct":2,"exp":"An actionable insight connects evidence with a decision or investigation while stating limitations.","module":15,"topic":"M15:Business Intelligence"}]},
  {"key":"M15:Automation","rows":[{"q":"Automation: What should be assessed before automating a workflow?","opts":["Process suitability","Exception handling","Control checks","Outcome monitoring"],"correct":0,"exp":"Suitability includes process clarity, reliability, risk and whether automation addresses a useful need.","module":15,"topic":"M15:Automation"},{"q":"Automation: What prevents an automated process from failing silently on an unusual case?","opts":["Process suitability","Control checks","Outcome monitoring","Exception handling"],"correct":3,"exp":"Exception handling provides defined routes for cases the normal flow cannot safely resolve.","module":15,"topic":"M15:Automation"},{"q":"Automation: What should validate that automation performs authorized actions accurately?","opts":["Process suitability","Exception handling","Outcome monitoring","Control checks"],"correct":3,"exp":"Control checks examine permissions, inputs and outputs with appropriate auditability.","module":15,"topic":"M15:Automation"},{"q":"Automation: What should verify after deployment that automation still improves work?","opts":["Outcome monitoring","Process suitability","Exception handling","Control checks"],"correct":0,"exp":"Outcome monitoring examines benefits, errors and unintended effects instead of assuming that less manual work guarantees value.","module":15,"topic":"M15:Automation"}]},
  {"key":"M15:Cybersecurity Awareness","rows":[{"q":"Cybersecurity Awareness: What should an employee do when a message unexpectedly requests credentials?","opts":["Use authorized access","Report promptly","Follow response instructions","Recognize suspicious activity"],"correct":3,"exp":"Recognize suspicious activity and verify through a trusted channel before supplying sensitive information.","module":15,"topic":"M15:Cybersecurity Awareness"},{"q":"Cybersecurity Awareness: What practice limits unnecessary exposure of business systems?","opts":["Recognize suspicious activity","Use authorized access","Report promptly","Follow response instructions"],"correct":1,"exp":"Authorized access gives people only appropriate permissions and uses the organization's approved protections.","module":15,"topic":"M15:Cybersecurity Awareness"},{"q":"Cybersecurity Awareness: What should follow discovering a possible security incident?","opts":["Recognize suspicious activity","Report promptly","Use authorized access","Follow response instructions"],"correct":1,"exp":"Prompt reporting through the approved route helps the responsible team investigate and contain harm.","module":15,"topic":"M15:Cybersecurity Awareness"},{"q":"Cybersecurity Awareness: What should employees do during an active incident response?","opts":["Recognize suspicious activity","Follow response instructions","Use authorized access","Report promptly"],"correct":1,"exp":"Follow verified response instructions and preserve relevant evidence rather than improvising disruptive actions.","module":15,"topic":"M15:Cybersecurity Awareness"}]},
  {"key":"M15:Cloud Computing Basics","rows":[{"q":"Cloud Computing Basics: What distinguishes a cloud service from a single local file?","opts":["Service model","On-demand service","Shared responsibility","Continuity planning"],"correct":1,"exp":"Cloud computing offers computing resources or services accessible on demand through a service arrangement.","module":15,"topic":"M15:Cloud Computing Basics"},{"q":"Cloud Computing Basics: What describes whether the provider supplies infrastructure, a platform or software?","opts":["Service model","On-demand service","Shared responsibility","Continuity planning"],"correct":0,"exp":"The service model affects the tasks retained by the customer and those handled by the provider.","module":15,"topic":"M15:Cloud Computing Basics"},{"q":"Cloud Computing Basics: What should a business understand about security duties when using cloud services?","opts":["On-demand service","Shared responsibility","Service model","Continuity planning"],"correct":1,"exp":"Shared responsibility varies by service and agreement; provider involvement does not remove all customer duties.","module":15,"topic":"M15:Cloud Computing Basics"},{"q":"Cloud Computing Basics: What should be prepared for a cloud outage or loss of access?","opts":["On-demand service","Service model","Continuity planning","Shared responsibility"],"correct":2,"exp":"Continuity planning considers recovery, data access, dependencies and feasible fallback arrangements.","module":15,"topic":"M15:Cloud Computing Basics"}]},
  {"key":"M15:Future Business Trends","rows":[{"q":"Future Business Trends: What should start a useful review of an emerging business trend?","opts":["Credibility assessment","Scenario exploration","Signal observation","Adaptive action"],"correct":2,"exp":"Signal observation records actual developments rather than assuming a popular claim is established.","module":15,"topic":"M15:Future Business Trends"},{"q":"Future Business Trends: What should be examined before using a trend prediction in strategy?","opts":["Signal observation","Scenario exploration","Credibility assessment","Adaptive action"],"correct":2,"exp":"Credibility assessment checks sources, evidence, assumptions and uncertainty.","module":15,"topic":"M15:Future Business Trends"},{"q":"Future Business Trends: What helps explore several possible effects of a trend?","opts":["Signal observation","Scenario exploration","Credibility assessment","Adaptive action"],"correct":1,"exp":"Scenario exploration examines plausible outcomes without presenting one as a certain forecast.","module":15,"topic":"M15:Future Business Trends"},{"q":"Future Business Trends: What is appropriate when trend evidence remains uncertain but potentially important?","opts":["Signal observation","Credibility assessment","Adaptive action","Scenario exploration"],"correct":2,"exp":"Adaptive action uses bounded tests, monitoring and review triggers rather than irreversible commitments based only on hype.","module":15,"topic":"M15:Future Business Trends"}]},
  {"key":"M16:Corporate Governance","rows":[{"q":"Corporate Governance: Which function oversees direction and management within the organization's governance arrangements?","opts":["Management execution","Board oversight","Decision rights","Accountability reporting"],"correct":1,"exp":"Board oversight examines strategy, performance and responsibilities while respecting the applicable organizational structure.","module":16,"topic":"M16:Corporate Governance"},{"q":"Corporate Governance: Which function carries out approved business plans and operations?","opts":["Management execution","Board oversight","Decision rights","Accountability reporting"],"correct":0,"exp":"Management execution implements direction and is accountable for delivery under assigned authority.","module":16,"topic":"M16:Corporate Governance"},{"q":"Corporate Governance: What clarifies who may authorize a significant decision?","opts":["Board oversight","Management execution","Decision rights","Accountability reporting"],"correct":2,"exp":"Decision rights allocate authority and escalation routes to reduce confusion and conflicts.","module":16,"topic":"M16:Corporate Governance"},{"q":"Corporate Governance: What enables the relevant oversight body to examine outcomes and conduct?","opts":["Board oversight","Accountability reporting","Management execution","Decision rights"],"correct":1,"exp":"Accountability reporting supplies material, reliable information for review and action.","module":16,"topic":"M16:Corporate Governance"}]},
  {"key":"M16:Business Ethics","rows":[{"q":"Business Ethics: What should a business examine before making a decision that shifts harm to another group?","opts":["Stakeholder effects","Conflict disclosure","Truthful representation","Responsible correction"],"correct":0,"exp":"Stakeholder effects include rights, obligations and foreseeable consequences beyond internal gain.","module":16,"topic":"M16:Business Ethics"},{"q":"Business Ethics: What should occur when a decision maker has a personal interest in a transaction?","opts":["Stakeholder effects","Truthful representation","Conflict disclosure","Responsible correction"],"correct":2,"exp":"Conflict disclosure enables appropriate safeguards and independent review where needed.","module":16,"topic":"M16:Business Ethics"},{"q":"Business Ethics: What should guide claims about an offering's capabilities?","opts":["Stakeholder effects","Conflict disclosure","Responsible correction","Truthful representation"],"correct":3,"exp":"Truthful representation uses supported statements and makes material limitations clear.","module":16,"topic":"M16:Business Ethics"},{"q":"Business Ethics: What should follow discovery of a misleading business claim?","opts":["Stakeholder effects","Responsible correction","Conflict disclosure","Truthful representation"],"correct":1,"exp":"Responsible correction addresses the claim and its effects and improves the process that produced it.","module":16,"topic":"M16:Business Ethics"}]},
  {"key":"M16:Compliance","rows":[{"q":"Compliance: What should be identified before declaring that a business process is compliant?","opts":["Applicable requirement","Assigned control","Evidence record","Issue escalation"],"correct":0,"exp":"Applicable requirements depend on jurisdiction, activity, contract and current rules.","module":16,"topic":"M16:Compliance"},{"q":"Compliance: What makes a compliance obligation part of actual work?","opts":["Assigned control","Applicable requirement","Evidence record","Issue escalation"],"correct":0,"exp":"An assigned control defines the action, responsible role and expected evidence.","module":16,"topic":"M16:Compliance"},{"q":"Compliance: What supports a later check that the required control operated?","opts":["Applicable requirement","Assigned control","Issue escalation","Evidence record"],"correct":3,"exp":"An evidence record documents the relevant action accurately and appropriately.","module":16,"topic":"M16:Compliance"},{"q":"Compliance: What should happen when a material compliance failure is identified?","opts":["Applicable requirement","Assigned control","Evidence record","Issue escalation"],"correct":3,"exp":"Issue escalation follows the approved route for assessment, correction and any required notification.","module":16,"topic":"M16:Compliance"}]},
  {"key":"M16:Risk Management","rows":[{"q":"Risk Management: What should a team do before choosing controls?","opts":["Risk identification","Risk assessment","Risk response","Residual risk review"],"correct":0,"exp":"Identification states the uncertain event, causes and possible effect on objectives.","module":16,"topic":"M16:Risk Management"},{"q":"Risk Management: What examines likelihood and impact in the context of the decision?","opts":["Risk identification","Risk assessment","Risk response","Residual risk review"],"correct":1,"exp":"Assessment prioritizes exposure using evidence and appropriate uncertainty.","module":16,"topic":"M16:Risk Management"},{"q":"Risk Management: What specifies a suitable action to address an identified risk?","opts":["Risk identification","Risk assessment","Risk response","Residual risk review"],"correct":2,"exp":"A response may reduce, avoid, share or accept risk with appropriate authority and ownership.","module":16,"topic":"M16:Risk Management"},{"q":"Risk Management: What should be reviewed after controls are implemented?","opts":["Risk identification","Residual risk review","Risk assessment","Risk response"],"correct":1,"exp":"Residual risk is the remaining exposure and must be checked rather than assumed eliminated.","module":16,"topic":"M16:Risk Management"}]},
  {"key":"M16:Corporate Social Responsibility (CSR)","rows":[{"q":"Corporate Social Responsibility (CSR): What should guide a company's social responsibility priorities?","opts":["Stakeholder responsibility","Relevant initiative","Impact evidence","Honest communication"],"correct":0,"exp":"Stakeholder responsibility considers material effects of the company's activities and obligations.","module":16,"topic":"M16:Corporate Social Responsibility (CSR)"},{"q":"Corporate Social Responsibility (CSR): What makes a CSR project more useful than an unrelated publicity exercise?","opts":["Stakeholder responsibility","Impact evidence","Honest communication","Relevant initiative"],"correct":3,"exp":"A relevant initiative addresses a meaningful issue with feasible actions and ownership.","module":16,"topic":"M16:Corporate Social Responsibility (CSR)"},{"q":"Corporate Social Responsibility (CSR): What should support a claim that the initiative benefited a community?","opts":["Stakeholder responsibility","Impact evidence","Relevant initiative","Honest communication"],"correct":1,"exp":"Impact evidence examines actual outcomes and limitations rather than donations or attendance alone.","module":16,"topic":"M16:Corporate Social Responsibility (CSR)"},{"q":"Corporate Social Responsibility (CSR): What prevents a social responsibility report from overstating success?","opts":["Stakeholder responsibility","Relevant initiative","Honest communication","Impact evidence"],"correct":2,"exp":"Honest communication distinguishes verified results, estimates and unresolved effects.","module":16,"topic":"M16:Corporate Social Responsibility (CSR)"}]},
  {"key":"M16:Sustainability","rows":[{"q":"Sustainability: What broad perspective should sustainability add to short-term business decisions?","opts":["Resource impact","Trade-off analysis","Measured improvement","Long-term viability"],"correct":3,"exp":"Long-term viability considers lasting organizational value and effects on relevant environmental and social systems.","module":16,"topic":"M16:Sustainability"},{"q":"Sustainability: What should be examined when production increases water or energy use?","opts":["Long-term viability","Resource impact","Trade-off analysis","Measured improvement"],"correct":1,"exp":"Resource impact considers actual use, local context and feasible alternatives.","module":16,"topic":"M16:Sustainability"},{"q":"Sustainability: What helps avoid claiming that every sustainability decision has no cost?","opts":["Long-term viability","Resource impact","Measured improvement","Trade-off analysis"],"correct":3,"exp":"Trade-off analysis makes consequences and competing considerations explicit.","module":16,"topic":"M16:Sustainability"},{"q":"Sustainability: What should support a claim that a sustainability change worked?","opts":["Long-term viability","Measured improvement","Resource impact","Trade-off analysis"],"correct":1,"exp":"Measured improvement uses a relevant baseline, method and period and reports limitations.","module":16,"topic":"M16:Sustainability"}]},
  {"key":"M16:Environmental, Social & Governance (ESG)","rows":[{"q":"Environmental, Social & Governance (ESG): Which ESG category most directly includes emissions and water use?","opts":["Social factor","Governance factor","Environmental factor","Reporting method"],"correct":2,"exp":"Environmental factors concern the organization's effects on ecological and physical systems.","module":16,"topic":"M16:Environmental, Social & Governance (ESG)"},{"q":"Environmental, Social & Governance (ESG): Which category most directly includes labor conditions and community effects?","opts":["Environmental factor","Social factor","Governance factor","Reporting method"],"correct":1,"exp":"Social factors consider people-related responsibilities and outcomes.","module":16,"topic":"M16:Environmental, Social & Governance (ESG)"},{"q":"Environmental, Social & Governance (ESG): Which category most directly includes oversight, controls and conflicts of interest?","opts":["Environmental factor","Social factor","Reporting method","Governance factor"],"correct":3,"exp":"Governance factors concern how decisions and accountability are organized.","module":16,"topic":"M16:Environmental, Social & Governance (ESG)"},{"q":"Environmental, Social & Governance (ESG): What should be checked before comparing two organizations' ESG scores?","opts":["Environmental factor","Social factor","Governance factor","Reporting method"],"correct":3,"exp":"Reporting methods, scope and assumptions can differ, so scores are not automatically equivalent or proof of ethical conduct.","module":16,"topic":"M16:Environmental, Social & Governance (ESG)"}]},
  {"key":"M16:Responsible Leadership","rows":[{"q":"Responsible Leadership: What should a leader seek when a decision affects people absent from the meeting?","opts":["Affected stakeholder voice","Evidence-based judgment","Accountable action","Learning and repair"],"correct":0,"exp":"Affected stakeholder voice reduces blind spots and makes relevant interests visible.","module":16,"topic":"M16:Responsible Leadership"},{"q":"Responsible Leadership: What should support a choice under uncertainty?","opts":["Affected stakeholder voice","Evidence-based judgment","Accountable action","Learning and repair"],"correct":1,"exp":"Evidence-based judgment distinguishes verified facts, assumptions and ethical responsibilities.","module":16,"topic":"M16:Responsible Leadership"},{"q":"Responsible Leadership: What turns a responsible decision into practice?","opts":["Affected stakeholder voice","Accountable action","Evidence-based judgment","Learning and repair"],"correct":1,"exp":"Accountable action assigns authority, resources, explanation and review of consequences.","module":16,"topic":"M16:Responsible Leadership"},{"q":"Responsible Leadership: What is required when a well-intended action produces harmful results?","opts":["Affected stakeholder voice","Evidence-based judgment","Accountable action","Learning and repair"],"correct":3,"exp":"Learning and repair acknowledge effects, correct harm and adjust the approach.","module":16,"topic":"M16:Responsible Leadership"}]},
  {"key":"M17:Executive Presence","rows":[{"q":"Executive Presence: What gives an executive's confidence a sound foundation?","opts":["Composed response","Clear reasoning","Respectful engagement","Prepared credibility"],"correct":3,"exp":"Prepared credibility rests on knowledge, honest evidence and reliable follow-through rather than appearance alone.","module":17,"topic":"M17:Executive Presence"},{"q":"Executive Presence: What helps a leader respond constructively under pressure?","opts":["Prepared credibility","Composed response","Clear reasoning","Respectful engagement"],"correct":1,"exp":"A composed response manages emotion while addressing the actual issue.","module":17,"topic":"M17:Executive Presence"},{"q":"Executive Presence: What makes an executive recommendation easier to assess?","opts":["Clear reasoning","Prepared credibility","Composed response","Respectful engagement"],"correct":0,"exp":"Clear reasoning connects the decision, evidence, trade-offs and proposed action.","module":17,"topic":"M17:Executive Presence"},{"q":"Executive Presence: What should characterize a leader's interaction with a less senior colleague?","opts":["Respectful engagement","Prepared credibility","Composed response","Clear reasoning"],"correct":0,"exp":"Respectful engagement values relevant contributions and protects dignity regardless of status.","module":17,"topic":"M17:Executive Presence"}]},
  {"key":"M17:Personal Branding","rows":[{"q":"Personal Branding: What should a professional reputation be based on?","opts":["Consistent conduct","Authentic capability","Relevant evidence","Audience fit"],"correct":1,"exp":"Authentic capability reflects skills and values actually demonstrated rather than an invented image.","module":17,"topic":"M17:Personal Branding"},{"q":"Personal Branding: What builds credibility across professional interactions?","opts":["Authentic capability","Relevant evidence","Audience fit","Consistent conduct"],"correct":3,"exp":"Consistent conduct aligns public claims with actual behavior and commitments.","module":17,"topic":"M17:Personal Branding"},{"q":"Personal Branding: What supports a claim of leadership impact on a profile?","opts":["Authentic capability","Consistent conduct","Relevant evidence","Audience fit"],"correct":2,"exp":"Relevant evidence uses accurate results, role descriptions and suitable work examples.","module":17,"topic":"M17:Personal Branding"},{"q":"Personal Branding: What helps a professional explain their strengths to a target employer?","opts":["Audience fit","Authentic capability","Consistent conduct","Relevant evidence"],"correct":0,"exp":"Audience fit emphasizes relevant experience without changing facts or exaggerating qualifications.","module":17,"topic":"M17:Personal Branding"}]},
  {"key":"M17:Professional Networking","rows":[{"q":"Professional Networking: What makes networking more useful than collecting contacts?","opts":["Relevant relationship","Respectful follow-up","Trustworthy conduct","Mutual value"],"correct":3,"exp":"Mutual value connects people through appropriate help, knowledge and shared interests.","module":17,"topic":"M17:Professional Networking"},{"q":"Professional Networking: What should guide choosing a professional community to join?","opts":["Mutual value","Respectful follow-up","Trustworthy conduct","Relevant relationship"],"correct":3,"exp":"A relevant relationship aligns with genuine learning or professional interests rather than status alone.","module":17,"topic":"M17:Professional Networking"},{"q":"Professional Networking: What should follow a useful introductory conversation?","opts":["Respectful follow-up","Mutual value","Relevant relationship","Trustworthy conduct"],"correct":0,"exp":"Respectful follow-up refers to the discussion and agreed next step without imposing unwanted requests.","module":17,"topic":"M17:Professional Networking"},{"q":"Professional Networking: What sustains a professional network over time?","opts":["Mutual value","Relevant relationship","Trustworthy conduct","Respectful follow-up"],"correct":2,"exp":"Trustworthy conduct honors commitments, respects confidentiality and communicates honestly.","module":17,"topic":"M17:Professional Networking"}]},
  {"key":"M17:Building a Leadership Portfolio","rows":[{"q":"Building a Leadership Portfolio: What helps a reader understand the challenge a portfolio project addressed?","opts":["Context statement","Role evidence","Outcome evidence","Reflective learning"],"correct":0,"exp":"A context statement explains the problem, stakeholders, constraints and intended outcome.","module":17,"topic":"M17:Building a Leadership Portfolio"},{"q":"Building a Leadership Portfolio: What distinguishes the learner's contribution from the whole team's work?","opts":["Context statement","Outcome evidence","Role evidence","Reflective learning"],"correct":2,"exp":"Role evidence accurately states decisions and actions the learner personally owned.","module":17,"topic":"M17:Building a Leadership Portfolio"},{"q":"Building a Leadership Portfolio: What supports a claim that the project achieved useful results?","opts":["Context statement","Role evidence","Outcome evidence","Reflective learning"],"correct":2,"exp":"Outcome evidence compares relevant baseline and results and identifies limitations.","module":17,"topic":"M17:Building a Leadership Portfolio"},{"q":"Building a Leadership Portfolio: What shows development beyond a polished deliverable?","opts":["Context statement","Reflective learning","Role evidence","Outcome evidence"],"correct":1,"exp":"Reflective learning examines choices, feedback, effects and improvements for future work.","module":17,"topic":"M17:Building a Leadership Portfolio"}]},
  {"key":"M17:Resume & LinkedIn Optimization","rows":[{"q":"Resume & LinkedIn Optimization: What should replace an unsupported claim of outstanding leadership?","opts":["Role relevance","Accurate achievement","Clear structure","Privacy judgment"],"correct":1,"exp":"An accurate achievement states the action and verified result without inventing figures or responsibility.","module":17,"topic":"M17:Resume & LinkedIn Optimization"},{"q":"Resume & LinkedIn Optimization: What should guide selecting examples for a target role?","opts":["Accurate achievement","Clear structure","Role relevance","Privacy judgment"],"correct":2,"exp":"Role relevance highlights capabilities required by the position while preserving truthful detail.","module":17,"topic":"M17:Resume & LinkedIn Optimization"},{"q":"Resume & LinkedIn Optimization: What helps a recruiter locate essential information quickly?","opts":["Accurate achievement","Clear structure","Role relevance","Privacy judgment"],"correct":1,"exp":"Clear structure uses readable sections and concise descriptions rather than unnecessary decoration.","module":17,"topic":"M17:Resume & LinkedIn Optimization"},{"q":"Resume & LinkedIn Optimization: What should be checked before posting a client project on a public profile?","opts":["Accurate achievement","Role relevance","Privacy judgment","Clear structure"],"correct":2,"exp":"Privacy judgment considers authorization and confidentiality and removes protected information.","module":17,"topic":"M17:Resume & LinkedIn Optimization"}]},
  {"key":"M17:Executive Interviews","rows":[{"q":"Executive Interviews: What supports an interview answer about resolving a leadership challenge?","opts":["Strategic reasoning","Honest limitation","Evidence-based example","Thoughtful question"],"correct":2,"exp":"An evidence-based example explains context, personal action and actual results.","module":17,"topic":"M17:Executive Interviews"},{"q":"Executive Interviews: What should an executive candidate show when comparing possible business choices?","opts":["Evidence-based example","Honest limitation","Strategic reasoning","Thoughtful question"],"correct":2,"exp":"Strategic reasoning connects objectives, evidence, trade-offs and stakeholders.","module":17,"topic":"M17:Executive Interviews"},{"q":"Executive Interviews: What should a candidate do when asked about experience they do not have?","opts":["Evidence-based example","Honest limitation","Strategic reasoning","Thoughtful question"],"correct":1,"exp":"An honest limitation avoids fabricated claims and can be paired with relevant transferable experience.","module":17,"topic":"M17:Executive Interviews"},{"q":"Executive Interviews: What helps the candidate assess expectations and organizational context?","opts":["Evidence-based example","Thoughtful question","Strategic reasoning","Honest limitation"],"correct":1,"exp":"A thoughtful question explores priorities, responsibilities and conditions for success.","module":17,"topic":"M17:Executive Interviews"}]},
  {"key":"M17:Career Planning","rows":[{"q":"Career Planning: What should career planning clarify before choosing development activities?","opts":["Capability gap","Development route","Progress review","Target role"],"correct":3,"exp":"A target role or direction identifies the capabilities and responsibilities being pursued.","module":17,"topic":"M17:Career Planning"},{"q":"Career Planning: What compares current evidence with the target role's requirements?","opts":["Target role","Development route","Progress review","Capability gap"],"correct":3,"exp":"A capability gap identifies specific knowledge, behavior or experience to develop.","module":17,"topic":"M17:Career Planning"},{"q":"Career Planning: What connects a gap with feasible learning and practice?","opts":["Target role","Capability gap","Development route","Progress review"],"correct":2,"exp":"A development route uses relevant activities, support and opportunities to demonstrate skill.","module":17,"topic":"M17:Career Planning"},{"q":"Career Planning: What keeps a career plan responsive to changing interests and evidence?","opts":["Target role","Progress review","Capability gap","Development route"],"correct":1,"exp":"Progress review checks development, feedback and fit and adjusts the direction when appropriate.","module":17,"topic":"M17:Career Planning"}]},
  {"key":"M17:Lifelong Learning","rows":[{"q":"Lifelong Learning: What should guide continuing professional study?","opts":["Deliberate practice","Feedback integration","Knowledge refresh","Learning priority"],"correct":3,"exp":"A learning priority connects a current or future need with a specific capability goal.","module":17,"topic":"M17:Lifelong Learning"},{"q":"Lifelong Learning: What builds capability more directly than repeating only comfortable tasks?","opts":["Learning priority","Feedback integration","Deliberate practice","Knowledge refresh"],"correct":2,"exp":"Deliberate practice targets a defined weakness with challenge, support and feedback.","module":17,"topic":"M17:Lifelong Learning"},{"q":"Lifelong Learning: What turns comments from others into useful development?","opts":["Learning priority","Deliberate practice","Knowledge refresh","Feedback integration"],"correct":3,"exp":"Feedback integration examines the evidence and applies a specific change that can be checked.","module":17,"topic":"M17:Lifelong Learning"},{"q":"Lifelong Learning: What prevents a leader from relying indefinitely on outdated rules or tools?","opts":["Knowledge refresh","Learning priority","Deliberate practice","Feedback integration"],"correct":0,"exp":"Knowledge refresh checks current authoritative information when requirements or technologies may have changed.","module":17,"topic":"M17:Lifelong Learning"}]}];
 var exams=[{"q":"A supervisor reverses an agreed priority without explanation. What should the supervisor do to restore reliable coordination?","opts":["Repeat the original deadline without discussion","Explain the changed evidence and renegotiate affected commitments","Privately hope each employee adapts","Treat questions as a refusal to cooperate"],"correct":1,"exp":"Leadership reliability requires communicating changed reasoning and its effect on commitments.","module":2,"topic":"M2:Examination scenario"},{"q":"A leader repeatedly takes over a colleague's delegated work at the first difficulty. What would better develop the colleague?","opts":["Retain every decision permanently","Remove all review checkpoints","Clarify boundaries and coach the colleague through a bounded attempt","Delegate the work without access to resources"],"correct":2,"exp":"Supported autonomy develops judgment while maintaining appropriate oversight.","module":2,"topic":"M2:Examination scenario"},{"q":"A team delivers its target by bypassing a stated ethical rule. What should the leader evaluate?","opts":["Only whether the target was reached","Only the team's speed","Only whether outsiders noticed","Both the outcome and the conduct used to achieve it"],"correct":3,"exp":"Leadership standards include how results are achieved, not just the numerical outcome.","module":2,"topic":"M2:Examination scenario"},{"q":"A colleague says a leader's promised follow-up never arrived. Which response shows accountability?","opts":["Explain that seniority removes the need to follow up","Check the record, acknowledge the lapse and agree a corrective action","Make a larger promise without checking capacity","Ask the colleague to stop raising the issue"],"correct":1,"exp":"Accountability responds to evidence and completes a realistic correction.","module":2,"topic":"M2:Examination scenario"},{"q":"A new leader asks for feedback but argues with every specific example. What change would make the process useful?","opts":["Request only positive comments","Replace feedback with a popularity vote","Treat all critical comments as personal attacks","Listen, verify the examples and select a behavior to practise"],"correct":3,"exp":"Learning requires examining feedback rather than defending every existing behavior.","module":2,"topic":"M2:Examination scenario"},{"q":"A confident team member disagrees with a leader's decision using relevant evidence. What is the strongest leadership response?","opts":["Examine the evidence and explain the resulting judgment","Use rank as the only reason to dismiss the point","Promise automatic agreement with all objections","Remove all responsibility from the colleague"],"correct":0,"exp":"Confidence and authority do not replace reasoned consideration of relevant evidence.","module":2,"topic":"M2:Examination scenario"},{"q":"A leadership development goal says become inspiring. What makes it more assessable?","opts":["Add more motivational adjectives","Define an observable behavior, practice date and feedback measure","Keep the goal private and undated","Measure only the number of meetings attended"],"correct":1,"exp":"Observable behaviors and review evidence make a development intention usable.","module":2,"topic":"M2:Examination scenario"},{"q":"A leader delegates responsibility but refuses every routine approval the task needs. What is the key correction?","opts":["Increase the task volume","Remove the employee's reporting access","Align necessary authority and resources with the responsibility","Evaluate the employee solely by missed deadlines"],"correct":2,"exp":"Responsibility is not feasible when the employee lacks the authority and resources required to act.","module":2,"topic":"M2:Examination scenario"},{"q":"A leader recognizes personal irritation during a meeting. What should follow awareness before replying?","opts":["Assume irritation proves the other person is wrong","Suppress all further participation from the team","Share an unverified accusation","Pause and choose a response suited to the issue"],"correct":3,"exp":"Self-awareness supports self-regulation and a constructive response to the actual issue.","module":2,"topic":"M2:Examination scenario"},{"q":"Two teams depend on the same specialist and both promise full-time access. What should their leaders do?","opts":["Agree priority, capacity and a shared allocation before committing","Ask the specialist to hide the conflict","Assign identical deadlines without checking workload","Judge effort only from hours online"],"correct":0,"exp":"Team coordination requires realistic capacity and clear agreements across competing demands.","module":5,"topic":"M5:Examination scenario"},{"q":"A profitable business cannot meet a payment due next week because customers pay later. What should a leader examine first?","opts":["Only the total revenue for the year","Only the company's logo and brand","The timing of expected receipts, payments and available cash","Only the number of completed sales meetings"],"correct":2,"exp":"Profit and cash availability differ; a short-term liquidity gap requires a timing-based forecast.","module":8,"topic":"M8:Examination scenario"},{"q":"A campaign doubles visits but sales stay unchanged. What should the marketing leader investigate?","opts":["Assume visits prove profitable growth","The defined conversion steps and relevant customer experience","Replace customer research with total impressions","Declare the entire product range unsuccessful"],"correct":1,"exp":"Visits are activity evidence; conversion analysis tests whether the intended customer action occurred.","module":9,"topic":"M9:Examination scenario"},{"q":"A renewal initiative contacts all customers repeatedly despite requests to stop. What should change?","opts":["Increase contact volume because retention is important","Ignore customer preferences if the list is large","Judge success only by messages sent","Use relevant, permitted contact and measure customer value"],"correct":3,"exp":"Retention requires responsible communication and useful value, not pressure or disregard for applicable data rules.","module":9,"topic":"M9:Examination scenario"},{"q":"A system launch has high training attendance but staff continue using the old process. What should the change leader examine?","opts":["Assume attendance proves adoption","Cancel all support because training occurred","Actual workflow barriers, access and adoption evidence","Publish another slogan without checking the workflow"],"correct":2,"exp":"Adoption depends on practical ability and behavior rather than training attendance alone.","module":10,"topic":"M10:Examination scenario"},{"q":"A pilot improves speed but creates more errors. What should happen before expansion?","opts":["Scale immediately because speed improved","Delete the error measure from reporting","Evaluate the combined effects and revise the pilot if needed","Declare all experimentation unsuitable"],"correct":2,"exp":"Change evaluation must consider quality and unintended effects alongside the intended benefit.","module":10,"topic":"M10:Examination scenario"},{"q":"A strategic business plan lists twelve priorities but has funding for only three. What makes it decision-ready?","opts":["Label every initiative urgent","Rank initiatives using explicit criteria and show the resource trade-offs","Omit funding constraints from the summary","Assign all initiatives the same completion date"],"correct":1,"exp":"A strategic plan must make feasible choices and resource implications visible.","module":18,"topic":"M18:Examination scenario"},{"q":"A team leadership project reports better collaboration but records no baseline or participant feedback. What evidence should be added?","opts":["Only a longer introduction","Only the leader's confidence rating","Comparable observations and relevant feedback before and after the intervention","Only a count of presentation slides"],"correct":2,"exp":"A credible project claim requires evidence connected to the stated outcome and intervention.","module":18,"topic":"M18:Examination scenario"},{"q":"An organizational improvement plan blames employees before mapping the workflow. What should the learner do?","opts":["Investigate actual handoffs, constraints and causes before selecting changes","Increase penalties for all delays","Copy a solution from an unrelated organization without checking fit","Remove staff from the analysis"],"correct":0,"exp":"Improvement requires evidence about the system rather than unsupported blame.","module":18,"topic":"M18:Examination scenario"},{"q":"A change management strategy contains announcements but no implementation support. What is missing?","opts":["Training, access, role clarity and routes for addressing barriers","Additional launch posters only","A larger project title","An assumption that silence means consent"],"correct":0,"exp":"A feasible change strategy enables people to perform the changed work.","module":18,"topic":"M18:Examination scenario"},{"q":"A marketing growth plan forecasts purchases without any evidence about the target customer. What should precede approval?","opts":["Treat the forecast as guaranteed revenue","Use total internet users as the demand estimate","Validate customer needs, channels and conversion assumptions through suitable research or tests","Hide the assumptions from reviewers"],"correct":2,"exp":"Market evidence and tested assumptions support a defensible growth plan.","module":18,"topic":"M18:Examination scenario"},{"q":"A financial performance review compares months using different cost classifications. What should be corrected?","opts":["Use comparable definitions or explicitly reconcile the differences","Choose the month with the better-looking result","Ignore all nonfinancial data","Assume every cost increase means lower efficiency"],"correct":0,"exp":"Consistent classification is necessary for meaningful comparison and interpretation.","module":18,"topic":"M18:Examination scenario"},{"q":"A business expansion proposal assumes the home-market approach works unchanged elsewhere. What should be examined?","opts":["Only the design of the new office","Only the founder's preferred location","Local demand, capabilities, operating conditions and applicable requirements","Only the current customer count"],"correct":2,"exp":"Expansion requires context-specific evidence rather than automatic transfer of assumptions.","module":18,"topic":"M18:Examination scenario"},{"q":"An executive presentation requests investment without showing alternatives or risks. What would strengthen it?","opts":["Add unsupported success statistics","Replace evidence with a motivational quotation","Remove all uncertainties","Show the decision, credible options, material risks and proposed action"],"correct":3,"exp":"Senior decisions require a clear recommendation supported by alternatives and material limitations.","module":18,"topic":"M18:Examination scenario"},{"q":"A leadership case study attributes success entirely to one manager despite several concurrent changes. What should the learner do?","opts":["Assert that timing proves causation","Exclude all team contributions","Use the manager's title as proof","Distinguish observed results from uncertain causal claims and consider other factors"],"correct":3,"exp":"A case study should state evidence and limitations rather than invent a single cause.","module":18,"topic":"M18:Examination scenario"},{"q":"A board meeting simulation gives every participant authority to approve the same major decision. What should be clarified?","opts":["Only the order of refreshments","Roles, decision rights, conflicts and the required approval process","Only the length of the room booking","Only the visual style of the minutes"],"correct":1,"exp":"Governance simulation requires realistic authority, oversight and an accurate record.","module":18,"topic":"M18:Examination scenario"},{"q":"A strategic plan project proposes a customer segment that the business cannot serve reliably. What should be revised?","opts":["Only the wording of the mission","The strategic choice or capability plan based on delivery feasibility","Only the plan's page count","Only the sales target upwards"],"correct":1,"exp":"Strategic value depends on a feasible connection between target market and capabilities.","module":18,"topic":"M18:Examination scenario"},{"q":"A team project uses confidential employee responses in a public presentation. What should happen?","opts":["Publish names to make the project impressive","Assume coursework removes confidentiality responsibilities","Discard every outcome measure","Check authorization and present suitably anonymized or aggregated evidence"],"correct":3,"exp":"Project evidence must be handled responsibly with appropriate permission and protection.","module":18,"topic":"M18:Examination scenario"},{"q":"An improvement plan promises a permanent gain after a one-day pilot. What should the learner add?","opts":["A guarantee of the same result in every setting","Longer or repeated checks and a clear statement of the evidence's limits","A larger decorative diagram","Only the pilot's fastest observation"],"correct":1,"exp":"Limited evidence does not establish durability; the plan should state limitations and verification needs.","module":18,"topic":"M18:Examination scenario"},{"q":"A growth proposal counts every new sale as immediately collected cash. What should be separated?","opts":["Sales and customer names only","Revenue assumptions and the timing of customer receipts","Marketing colors and channel names","Supplier logos and employee titles"],"correct":1,"exp":"Revenue and cash timing may differ and both affect a feasible growth plan.","module":18,"topic":"M18:Examination scenario"},{"q":"A simulated board member has a personal interest in a proposed contract. What should the record show?","opts":["Automatic approval because the relationship is known","Omission of the relationship to simplify the minutes","Disclosure and the applicable independent review or recusal process","Only the supplier's advertising material"],"correct":2,"exp":"Conflict handling protects decision integrity through transparent and appropriate safeguards.","module":18,"topic":"M18:Examination scenario"},{"q":"A capstone challenge is so broad that no deliverable can be finished within the course. What should the learner do?","opts":["Define a bounded problem, feasible scope and measurable outcome","Add more unrelated business functions","Keep the scope vague until the final presentation","Promise complete organizational transformation"],"correct":0,"exp":"A bounded challenge makes implementation and assessment feasible.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone business analysis relies on old figures without describing their source. What should be improved?","opts":["Verify source, period, definitions and limitations before using the figures","Treat precision in the chart as proof of accuracy","Remove the analysis and keep only a slogan","Present estimates as audited results"],"correct":0,"exp":"Business analysis requires reliable evidence and an explicit account of uncertainty.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone strategy proposes two initiatives that require the same limited budget. What should be explicit?","opts":["A claim that both can proceed without funding","Only the project names","Only the learner's preference","The priority choice, opportunity cost and funding implications"],"correct":3,"exp":"Coherent strategy makes resource trade-offs visible and justified.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone people plan assigns responsibilities to stakeholders who have not been consulted. What should precede implementation?","opts":["Assume their names establish consent","Remove all review checkpoints","Confirm roles, capacity, authority and support with the affected people","Measure cooperation only through attendance"],"correct":2,"exp":"Implementation depends on agreed, feasible responsibilities and stakeholder engagement.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone financial plan includes one optimistic forecast and no sensitivity checks. What would strengthen it?","opts":["Test material assumptions under plausible alternative conditions","Present optimism as certainty","Exclude all cost assumptions","Increase every projected figure equally"],"correct":0,"exp":"Sensitivity and scenario checks help assess financial feasibility under uncertainty.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone implementation strategy has milestones but no owners. What is needed?","opts":["More decorative milestone icons","Named responsibility, resources and escalation for the milestones","Only a longer timeline","An assumption that everyone will share every task"],"correct":1,"exp":"Execution requires clear ownership as well as dates.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone presentation reports an unfinished trial as a completed organizational benefit. What should change?","opts":["Describe all proposals as achievements","Hide the trial's duration","Use the largest possible estimate without qualification","Separate delivered results, provisional findings and proposed future work"],"correct":3,"exp":"Honest presentation distinguishes what occurred from what remains unverified or proposed.","module":19,"topic":"M19:Examination scenario"},{"q":"An executive review finds that the capstone's result measure does not match its stated objective. What should the learner do?","opts":["Revise the measure or objective and explain the mismatch","Keep the measure because it looks favorable","Remove the objective from the portfolio","Treat reviewer questions as irrelevant"],"correct":0,"exp":"Assessment evidence must relate to the intended outcome rather than merely being available.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone plan includes sensitive customer records in its appendix. What should be checked?","opts":["Whether the appendix uses attractive colors","Whether the customer list is long enough","Authorization, necessity and appropriate anonymization before sharing","Whether names make the project seem realistic"],"correct":2,"exp":"Responsible evidence use protects confidential and personal information.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone predicts a technology benefit without testing how employees will use the system. What should be added?","opts":["An assumption that purchase proves success","A bounded workflow pilot with adoption and outcome measures","A promise that training is unnecessary","A plan to remove all human review"],"correct":1,"exp":"Technology value depends on actual use, suitable workflow and verified results.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone risk register lists issues but assigns no follow-up. What is required?","opts":["A larger list of generic risk words","Owners, responses, review dates and relevant escalation triggers","A claim that recording risk eliminates it","A guarantee that none of the risks will occur"],"correct":1,"exp":"Risk management requires action and monitoring beyond listing exposures.","module":19,"topic":"M19:Examination scenario"},{"q":"A leadership portfolio shows only group outcomes without explaining the learner's contribution. What should be added?","opts":["Accurate personal responsibilities, decisions and supporting evidence","A claim that the learner owned every result","Only more photos of the team","Only the project's total budget"],"correct":0,"exp":"A portfolio should distinguish personal contribution from collective achievement.","module":19,"topic":"M19:Examination scenario"},{"q":"A learner received critical project feedback but omits it from their reflection. What would demonstrate learning?","opts":["State that excellent leaders receive no criticism","Delete every reference to limitations","Explain the feedback, response, evidence and next development action","Replace the reflection with a certificate image"],"correct":2,"exp":"Reflection demonstrates development through examination and application of feedback.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone intervention improved one department while increasing another's workload. What should the review consider?","opts":["Only the benefiting department's result","The combined stakeholder effects and whether the change needs adjustment","Only the leader's presentation score","Only whether the original target was met"],"correct":1,"exp":"Integrated leadership evaluates consequences across affected stakeholders.","module":19,"topic":"M19:Examination scenario"},{"q":"A portfolio includes a planned activity as if it already happened. What should be corrected?","opts":["Use past tense for every planned action","Remove dates to conceal the difference","Label completed work, ongoing work and future plans accurately","Count intended outcomes as verified results"],"correct":2,"exp":"An honest portfolio clearly distinguishes demonstrated achievement from intention.","module":19,"topic":"M19:Examination scenario"}];
 var topics={},practice={};
 DATA.forEach(function(t){topics[t.key]=t.rows;practice[t.key]=t.rows.slice(0,3);});
 window.TIH_LEADERSHIP_QUESTIONS={revision:1,topics:topics,exams:exams};
 window.TIH_TOPIC_QUIZZES=window.TIH_TOPIC_QUIZZES||{};window.TIH_TOPIC_QUIZZES.leadership=practice;
})();
